  "Submit a correction for a missed or incorrect punch. Your manager will review and approve within the regularization cutoff window (7 days after month end).": "ತಪ್ಪಿದ ಅಥವಾ ತಪ್ಪಾದ ಪಂಚ್‌ಗೆ ತಿದ್ದುಪಡಿಯನ್ನು ಸಲ್ಲಿಸಿ. ಕ್ರಮಬದ್ಧಗೊಳಿಸುವ ಕೊನೆಯ ದಿನಾಂಕದೊಳಗೆ (ತಿಂಗಳ ಅಂತ್ಯದಿಂದ 7 ದಿನಗಳು) ನಿಮ್ಮ ಮ್ಯಾನೇಜರ್ ಪರಿಶೀಲಿಸಿ ಅನುಮೋದಿಸುತ್ತಾರೆ.",
