  // Home banner, tax notices and late-login text
  "You are viewing this workspace read-only. Nothing you do here is saved.": "ನೀವು ಈ ಕಾರ್ಯಕ್ಷೇತ್ರವನ್ನು ವೀಕ್ಷಣೆಗೆ ಮಾತ್ರ ತೆರೆದಿದ್ದೀರಿ. ಇಲ್ಲಿ ನೀವು ಮಾಡುವ ಯಾವುದೂ ಉಳಿಸಲ್ಪಡುವುದಿಲ್ಲ.",
  "Requests are recorded against your employee record and routed to the approver shown on each one.": "ವಿನಂತಿಗಳನ್ನು ನಿಮ್ಮ ಉದ್ಯೋಗಿ ದಾಖಲೆಯಲ್ಲಿ ದಾಖಲಿಸಲಾಗುತ್ತದೆ ಮತ್ತು ಪ್ರತಿಯೊಂದರಲ್ಲಿ ತೋರಿಸಿರುವ ಅನುಮೋದಕರಿಗೆ ಕಳುಹಿಸಲಾಗುತ್ತದೆ.",
  "Tax declaration approved": "ತೆರಿಗೆ ಘೋಷಣೆ ಅನುಮೋದಿತ",
  "Tax declaration window is open": "ತೆರಿಗೆ ಘೋಷಣೆಯ ಅವಧಿ ತೆರೆದಿದೆ",
  "Your {year} regime and declarations were approved. Further changes follow payroll approval.": "ನಿಮ್ಮ {year} ರ ತೆರಿಗೆ ವ್ಯವಸ್ಥೆ ಮತ್ತು ಘೋಷಣೆಗಳನ್ನು ಅನುಮೋದಿಸಲಾಗಿದೆ. ಮುಂದಿನ ಬದಲಾವಣೆಗಳು ಪೇರೋಲ್ ಅನುಮೋದನೆಯ ಪ್ರಕಾರ ನಡೆಯುತ್ತವೆ.",
  "Review your {year} regime and declarations before {date}. Changes follow payroll approval.": "{date} ಒಳಗೆ ನಿಮ್ಮ {year} ರ ತೆರಿಗೆ ವ್ಯವಸ್ಥೆ ಮತ್ತು ಘೋಷಣೆಗಳನ್ನು ಪರಿಶೀಲಿಸಿ. ಬದಲಾವಣೆಗಳು ಪೇರೋಲ್ ಅನುಮೋದನೆಯ ಪ್ರಕಾರ ನಡೆಯುತ್ತವೆ.",
