  "Cards": "ಕಾರ್ಡ್‌ಗಳು",
  "Changes employees ask HR to make to their profile. Everyone who answers HR Help tickets, and any full-access user, sees all of them.": "ಉದ್ಯೋಗಿಗಳು ತಮ್ಮ ಪ್ರೊಫೈಲ್‌ನಲ್ಲಿ ಮಾಡಲು HR ಅನ್ನು ಕೇಳುವ ಬದಲಾವಣೆಗಳು. HR ಸಹಾಯ ಟಿಕೆಟ್‌ಗಳಿಗೆ ಉತ್ತರಿಸುವ ಎಲ್ಲರೂ ಮತ್ತು ಪೂರ್ಣ ಪ್ರವೇಶ ಹೊಂದಿರುವ ಯಾವುದೇ ಬಳಕೆದಾರರು ಅವೆಲ್ಲವನ್ನೂ ನೋಡುತ್ತಾರೆ.",
  "Counts show only what the server lets you see. Onboarding approvals are in Review & Onboarding, and bank-change requests are in the employee record; they are not part of this list.": "ಸರ್ವರ್ ನಿಮಗೆ ನೋಡಲು ಅನುಮತಿಸುವುದನ್ನು ಮಾತ್ರ ಸಂಖ್ಯೆಗಳು ತೋರಿಸುತ್ತವೆ. ಆನ್‌ಬೋರ್ಡಿಂಗ್ ಅನುಮೋದನೆಗಳು \"ಪರಿಶೀಲನೆ ಮತ್ತು ಆನ್‌ಬೋರ್ಡಿಂಗ್\" ನಲ್ಲಿವೆ, ಮತ್ತು ಬ್ಯಾಂಕ್ ಬದಲಾವಣೆ ವಿನಂತಿಗಳು ಉದ್ಯೋಗಿ ದಾಖಲೆಯಲ್ಲಿವೆ; ಅವು ಈ ಪಟ್ಟಿಯ ಭಾಗವಲ್ಲ.",
  "Cycle sign-off for your team or payroll scope. Open the tab to see what is due.": "ನಿಮ್ಮ ತಂಡ ಅಥವಾ ಪೇರೋಲ್ ವ್ಯಾಪ್ತಿಯ ಚಕ್ರ ಸಹಿ. ಯಾವುದು ಬಾಕಿ ಇದೆ ಎಂದು ನೋಡಲು ಟ್ಯಾಬ್ ತೆರೆಯಿರಿ.",
  "Employees assigned to you; with no assigned HR, employees on your branch. A full-access user sees all.": "ನಿಮಗೆ ನಿಯೋಜಿತ ಉದ್ಯೋಗಿಗಳು; ನಿಯೋಜಿತ HR ಇಲ್ಲದಿದ್ದರೆ, ನಿಮ್ಮ ಶಾಖೆಯ ಉದ್ಯೋಗಿಗಳು. ಪೂರ್ಣ ಪ್ರವೇಶ ಹೊಂದಿರುವ ಬಳಕೆದಾರರು ಎಲ್ಲವನ್ನೂ ನೋಡುತ್ತಾರೆ.",
