  "9 hours": "9 ಗಂಟೆಗಳು",
  "A fallback punch must still be from inside the office geofence. It is flagged on the punch and recorded in the Audit Log.": "ಪರ್ಯಾಯ ಪಂಚ್ ಕೂಡ ಕಚೇರಿಯ ಜಿಯೋಫೆನ್ಸ್ ಒಳಗಿಂದಲೇ ಆಗಿರಬೇಕು. ಅದನ್ನು ಪಂಚ್‌ನಲ್ಲಿ ಗುರುತಿಸಲಾಗುತ್ತದೆ ಮತ್ತು ಆಡಿಟ್ ಲಾಗ್‌ನಲ್ಲಿ ದಾಖಲಿಸಲಾಗುತ್ತದೆ.",
