  "Every message (the clock-in error, the Profile page, the Face ID Registrations screen, the hire screen and the welcome email) follows this choice.": "ಪ್ರತಿ ಸಂದೇಶವೂ (ಕ್ಲಾಕ್-ಇನ್ ದೋಷ, ಪ್ರೊಫೈಲ್ ಪುಟ, Face ID ನೋಂದಣಿ ಪರದೆ, ನೇಮಕಾತಿ ಪರದೆ ಮತ್ತು ಸ್ವಾಗತ ಇಮೇಲ್) ಈ ಆಯ್ಕೆಯನ್ನೇ ಅನುಸರಿಸುತ್ತದೆ.",
  "Face ID registration is": "Face ID ನೋಂದಣಿ",
  "Face ID Verification": "Face ID ಪರಿಶೀಲನೆ",
  "Face ID verification is": "Face ID ಪರಿಶೀಲನೆ",
  "for every employee. Every web punch needs a live face match against an approved Face ID; until one exists, web clock-in/out is blocked unless you allow the fallback below.": "ಪ್ರತಿ ಉದ್ಯೋಗಿಗೆ. ಪ್ರತಿ ವೆಬ್ ಪಂಚ್‌ಗೂ ಅನುಮೋದಿತ Face ID ಯೊಂದಿಗೆ ನೇರ ಮುಖ ಹೊಂದಾಣಿಕೆ ಬೇಕು; ಅದು ಇರುವವರೆಗೆ, ಕೆಳಗಿನ ಪರ್ಯಾಯವನ್ನು ಅನುಮತಿಸದ ಹೊರತು ವೆಬ್ ಕ್ಲಾಕ್-ಇನ್/ಔಟ್ ತಡೆಹಿಡಿಯಲಾಗುತ್ತದೆ.",
  "Forgive late arrival when full hours are completed": "ಪೂರ್ಣ ಗಂಟೆಗಳನ್ನು ಪೂರೈಸಿದರೆ ತಡವಾಗಿ ಬಂದುದನ್ನು ಕ್ಷಮಿಸಿ",
  "Grace Period (min)": "ರಿಯಾಯಿತಿ ಅವಧಿ (ನಿಮಿಷ)",
