  "How many days back an employee can request work from home. Not allowed (recommended): today or a later date only, because an approved request for a past day relabels that day after the fact and the home-location check cannot be met.": "ಉದ್ಯೋಗಿ ಎಷ್ಟು ದಿನ ಹಿಂದಿನದಕ್ಕೆ ಮನೆಯಿಂದ ಕೆಲಸಕ್ಕೆ ವಿನಂತಿಸಬಹುದು. ಅನುಮತಿ ಇಲ್ಲ (ಶಿಫಾರಸು): ಇಂದು ಅಥವಾ ನಂತರದ ದಿನಾಂಕ ಮಾತ್ರ, ಏಕೆಂದರೆ ಹಿಂದಿನ ದಿನಕ್ಕೆ ಅನುಮೋದಿತ ವಿನಂತಿಯು ಆ ದಿನವನ್ನು ನಂತರ ಬದಲಾಯಿಸುತ್ತದೆ ಮತ್ತು ಮನೆಯ ಸ್ಥಳ ಪರಿಶೀಲನೆಯನ್ನು ಪೂರೈಸಲು ಸಾಧ್ಯವಿಲ್ಲ.",
  "HR only": "HR ಮಾತ್ರ",
  "Late Mark & LOP Rule": "ತಡ ಗುರುತು ಮತ್ತು ವೇತನ ಕಡಿತ ನಿಯಮ",
  "Late Marks per LOP": "ಪ್ರತಿ ವೇತನ ಕಡಿತಕ್ಕೆ ತಡ ಗುರುತುಗಳು",
