  "Notify HR and the manager when an employee is absent for N+ consecutive working days without approved leave.": "ಅನುಮೋದಿತ ರಜೆ ಇಲ್ಲದೆ ಉದ್ಯೋಗಿ ಸತತ N+ ಕೆಲಸದ ದಿನಗಳು ಗೈರುಹಾಜರಾದಾಗ HR ಮತ್ತು ಮ್ಯಾನೇಜರ್‌ಗೆ ತಿಳಿಸಿ.",
  "off": "ಆಫ್",
  "Off (recommended): a finished day of the half-day limit or fewer is a Half Day; a day above it but short of the full-day minimum stays Present and is shown as “hours not completed” with the minutes short. On: every day below the full-day minimum is a Half Day.": "ಆಫ್ (ಶಿಫಾರಸು): ಅರ್ಧ ದಿನದ ಮಿತಿ ಅಥವಾ ಅದಕ್ಕಿಂತ ಕಡಿಮೆ ಗಂಟೆ ಕೆಲಸ ಮಾಡಿ ಮುಗಿದ ದಿನ ಅರ್ಧ ದಿನ; ಅದಕ್ಕಿಂತ ಹೆಚ್ಚಿದ್ದು ಪೂರ್ಣ ದಿನದ ಕನಿಷ್ಠಕ್ಕಿಂತ ಕಡಿಮೆ ಇರುವ ದಿನ ಹಾಜರು ಎಂದೇ ಉಳಿಯುತ್ತದೆ ಮತ್ತು ಕಡಿಮೆ ಇರುವ ನಿಮಿಷಗಳೊಂದಿಗೆ “ಗಂಟೆಗಳು ಪೂರ್ಣಗೊಂಡಿಲ್ಲ” ಎಂದು ತೋರಿಸಲಾಗುತ್ತದೆ. ಆನ್: ಪೂರ್ಣ ದಿನದ ಕನಿಷ್ಠಕ್ಕಿಂತ ಕಡಿಮೆ ಇರುವ ಪ್ರತಿ ದಿನವೂ ಅರ್ಧ ದಿನ.",
  "OT Multiplier — Holiday": "ಓವರ್‌ಟೈಮ್ ಗುಣಕ — ರಜಾದಿನ",
