  "Someone who arrives after the grace period but works the full-day hours is marked Present and gets no late mark. The late arrival stays as a note.": "ರಿಯಾಯಿತಿ ಅವಧಿಯ ನಂತರ ಬಂದರೂ ಪೂರ್ಣ ದಿನದ ಗಂಟೆಗಳನ್ನು ಕೆಲಸ ಮಾಡಿದವರನ್ನು ಹಾಜರು ಎಂದು ಗುರುತಿಸಲಾಗುತ್ತದೆ ಮತ್ತು ತಡ ಗುರುತು ಹಾಕುವುದಿಲ್ಲ. ತಡವಾಗಿ ಬಂದ ವಿಷಯ ಟಿಪ್ಪಣಿಯಾಗಿ ಉಳಿಯುತ್ತದೆ.",
