  "Applies to every active employee matching the filters below — resolved on the server, so no employee list needs to load into the browser first.": "ಕೆಳಗಿನ ಫಿಲ್ಟರ್‌ಗಳಿಗೆ ಹೊಂದುವ ಪ್ರತಿ ಸಕ್ರಿಯ ಉದ್ಯೋಗಿಗೆ ಅನ್ವಯಿಸುತ್ತದೆ — ಸರ್ವರ್‌ನಲ್ಲಿ ನಿರ್ಧರಿಸಲಾಗುತ್ತದೆ, ಆದ್ದರಿಂದ ಮೊದಲು ಬ್ರೌಸರ್‌ಗೆ ಉದ್ಯೋಗಿ ಪಟ್ಟಿ ಲೋಡ್ ಆಗಬೇಕಿಲ್ಲ.",
