  "every active employee (no branch/department filter)": "ಪ್ರತಿ ಸಕ್ರಿಯ ಉದ್ಯೋಗಿ (ಶಾಖೆ/ವಿಭಾಗ ಫಿಲ್ಟರ್ ಇಲ್ಲ)",
  "Failed to assign pattern.": "ಮಾದರಿಯನ್ನು ನಿಯೋಜಿಸಲು ಸಾಧ್ಯವಾಗಲಿಲ್ಲ.",
  "Past attendance is never affected — this pattern applies from the effective date forward only.": "ಹಿಂದಿನ ಹಾಜರಾತಿಗೆ ಎಂದಿಗೂ ಪರಿಣಾಮವಿಲ್ಲ — ಈ ಮಾದರಿ ಜಾರಿ ದಿನಾಂಕದಿಂದ ಮುಂದಕ್ಕೆ ಮಾತ್ರ ಅನ್ವಯಿಸುತ್ತದೆ.",
  "Select pattern…": "ಮಾದರಿ ಆಯ್ಕೆಮಾಡಿ…",
  "the selected pattern": "ಆಯ್ಕೆಮಾಡಿದ ಮಾದರಿ",
  "This assigns \"{pattern}\" effective {date} to every active employee matching: {scope}. The exact number of employees affected is resolved on the server and isn't known until this runs.": "ಇದು \"{pattern}\" ಅನ್ನು {date} ರಿಂದ ಜಾರಿಗೆ ಬರುವಂತೆ ಹೊಂದುವ ಪ್ರತಿ ಸಕ್ರಿಯ ಉದ್ಯೋಗಿಗೆ ನಿಯೋಜಿಸುತ್ತದೆ: {scope}. ಪರಿಣಾಮ ಬೀರುವ ಉದ್ಯೋಗಿಗಳ ನಿಖರ ಸಂಖ್ಯೆಯನ್ನು ಸರ್ವರ್‌ನಲ್ಲಿ ನಿರ್ಧರಿಸಲಾಗುತ್ತದೆ ಮತ್ತು ಇದು ಚಾಲನೆಯಾಗುವವರೆಗೆ ತಿಳಿಯುವುದಿಲ್ಲ.",
  "Try clearing a filter above.": "ಮೇಲಿನ ಫಿಲ್ಟರ್ ಅನ್ನು ತೆರವುಗೊಳಿಸಿ ನೋಡಿ.",
  "Weekly Off Pattern": "ವಾರದ ರಜೆ ಮಾದರಿ",
  "Weekly off pattern assigned to {count} employee(s).": "ವಾರದ ರಜೆ ಮಾದರಿಯನ್ನು {count} ಉದ್ಯೋಗಿ(ಗಳಿಗೆ) ನಿಯೋಜಿಸಲಾಗಿದೆ.",
  "Weekly off pattern assigned to {name}.": "ವಾರದ ರಜೆ ಮಾದರಿಯನ್ನು {name} ಅವರಿಗೆ ನಿಯೋಜಿಸಲಾಗಿದೆ.",
  "Which weekly off pattern each employee follows. A new pattern applies from its effective date forward.": "ಪ್ರತಿ ಉದ್ಯೋಗಿ ಯಾವ ವಾರದ ರಜೆ ಮಾದರಿಯನ್ನು ಅನುಸರಿಸುತ್ತಾರೆ. ಹೊಸ ಮಾದರಿ ಅದರ ಜಾರಿ ದಿನಾಂಕದಿಂದ ಮುಂದಕ್ಕೆ ಅನ್ವಯಿಸುತ್ತದೆ.",
  "\"{name}\" will be deactivated. Employees currently assigned this pattern keep it until reassigned — history is preserved.": "\"{name}\" ಅನ್ನು ನಿಷ್ಕ್ರಿಯಗೊಳಿಸಲಾಗುತ್ತದೆ. ಪ್ರಸ್ತುತ ಈ ಮಾದರಿ ನಿಯೋಜಿತ ಉದ್ಯೋಗಿಗಳು ಮರುನಿಯೋಜಿಸುವವರೆಗೆ ಅದನ್ನೇ ಉಳಿಸಿಕೊಳ್ಳುತ್ತಾರೆ — ಇತಿಹಾಸವನ್ನು ಸಂರಕ್ಷಿಸಲಾಗುತ್ತದೆ.",
