  "Configure reusable weekly-off schedules and assign them to employees from Attendance & Time → Weekly Off Assignment.": "ಮರುಬಳಕೆ ಮಾಡಬಹುದಾದ ವಾರದ ರಜೆ ವೇಳಾಪಟ್ಟಿಗಳನ್ನು ಹೊಂದಿಸಿ ಮತ್ತು ಹಾಜರಾತಿ ಮತ್ತು ಸಮಯ → ವಾರದ ರಜೆ ನಿಗದಿ ಮೂಲಕ ಉದ್ಯೋಗಿಗಳಿಗೆ ನಿಯೋಜಿಸಿ.",
