  "Checking…": "ಪರಿಶೀಲಿಸಲಾಗುತ್ತಿದೆ…",
  "Could not read this device's location. Allow location access and try again.": "ಈ ಸಾಧನದ ಸ್ಥಳವನ್ನು ಪಡೆಯಲು ಸಾಧ್ಯವಾಗಲಿಲ್ಲ. ಸ್ಥಳ ಪ್ರವೇಶಕ್ಕೆ ಅನುಮತಿ ನೀಡಿ ಮತ್ತು ಮತ್ತೆ ಪ್ರಯತ್ನಿಸಿ.",
  "Enter both coordinates to see the office on a map.": "ನಕ್ಷೆಯಲ್ಲಿ ಕಚೇರಿಯನ್ನು ನೋಡಲು ಎರಡೂ ನಿರ್ದೇಶಾಂಕಗಳನ್ನು ನಮೂದಿಸಿ.",
  "Office location": "ಕಚೇರಿ ಸ್ಥಳ",
  "Open in OpenStreetMap": "OpenStreetMap ನಲ್ಲಿ ತೆರೆಯಿರಿ",
  "the allowed": "ಅನುಮತಿಸಿದ",
  "The pin is where punches are measured from. Employees must be within {radius} m of it.": "ಪಂಚ್‌ಗಳನ್ನು ಈ ಪಿನ್‌ನಿಂದ ಅಳೆಯಲಾಗುತ್ತದೆ. ಉದ್ಯೋಗಿಗಳು ಇದರಿಂದ {radius} ಮೀ ಒಳಗೆ ಇರಬೇಕು.",
  "This browser cannot share its location.": "ಈ ಬ್ರೌಸರ್ ತನ್ನ ಸ್ಥಳವನ್ನು ಹಂಚಿಕೊಳ್ಳಲು ಸಾಧ್ಯವಿಲ್ಲ.",
  "Use my current location": "ನನ್ನ ಪ್ರಸ್ತುತ ಸ್ಥಳ ಬಳಸಿ",
  "— only one on file, used automatically": "— ಒಂದೇ ಒಂದು ದಾಖಲೆಯಲ್ಲಿದೆ, ಸ್ವಯಂಚಾಲಿತವಾಗಿ ಬಳಸಲಾಗುತ್ತದೆ",
  "{stateName} has {count} GST registrations. Pick the one this office uses.": "{stateName} ನಲ್ಲಿ {count} GST ನೋಂದಣಿಗಳಿವೆ. ಈ ಕಚೇರಿ ಬಳಸುವುದನ್ನು ಆಯ್ಕೆಮಾಡಿ.",
  "Add one in Company Profile": "ಕಂಪನಿ ಪ್ರೊಫೈಲ್‌ನಲ್ಲಿ ಒಂದನ್ನು ಸೇರಿಸಿ",
  "City": "ನಗರ",
  "Enter new city name": "ಹೊಸ ನಗರದ ಹೆಸರನ್ನು ನಮೂದಿಸಿ",
  "GST Registration": "GST ನೋಂದಣಿ",
  "Loading cities…": "ನಗರಗಳು ಲೋಡ್ ಆಗುತ್ತಿವೆ…",
