  "Select State": "ರಾಜ್ಯವನ್ನು ಆಯ್ಕೆಮಾಡಿ",
  "Select which GST registration this Company Code uses…": "ಈ ಕಂಪನಿ ಕೋಡ್ ಬಳಸುವ GST ನೋಂದಣಿಯನ್ನು ಆಯ್ಕೆಮಾಡಿ…",
  "State/Region": "ರಾಜ್ಯ/ಪ್ರದೇಶ",
  "There is no GST registration for": "GST ನೋಂದಣಿ ಇಲ್ಲ:",
  "yet. This office will need one.": "ಇನ್ನೂ ಆಗಿಲ್ಲ. ಈ ಕಚೇರಿಗೆ ಒಂದು ಬೇಕಾಗುತ್ತದೆ.",
  "{branchName} was created and its Company Code Admin was assigned.": "{branchName} ಅನ್ನು ರಚಿಸಲಾಗಿದೆ ಮತ್ತು ಅದರ ಕಂಪನಿ ಕೋಡ್ ಅಡ್ಮಿನ್ ಅನ್ನು ನಿಯೋಜಿಸಲಾಗಿದೆ.",
  "{branchName} was created and its Company Code Admin was invited by email.": "{branchName} ಅನ್ನು ರಚಿಸಲಾಗಿದೆ ಮತ್ತು ಅದರ ಕಂಪನಿ ಕೋಡ್ ಅಡ್ಮಿನ್‌ಗೆ ಇಮೇಲ್ ಮೂಲಕ ಆಹ್ವಾನ ಕಳುಹಿಸಲಾಗಿದೆ.",
  "{branchName} was created, but assigning its Company Code Admin failed: {reason} — use the Employees page instead.": "{branchName} ಅನ್ನು ರಚಿಸಲಾಗಿದೆ, ಆದರೆ ಅದರ ಕಂಪನಿ ಕೋಡ್ ಅಡ್ಮಿನ್ ನಿಯೋಜನೆ ವಿಫಲವಾಯಿತು: {reason} — ಬದಲಿಗೆ ಉದ್ಯೋಗಿಗಳ ಪುಟವನ್ನು ಬಳಸಿ.",
  "{branchName} was updated and its Company Code Admin was assigned.": "{branchName} ಅನ್ನು ನವೀಕರಿಸಲಾಗಿದೆ ಮತ್ತು ಅದರ ಕಂಪನಿ ಕೋಡ್ ಅಡ್ಮಿನ್ ಅನ್ನು ನಿಯೋಜಿಸಲಾಗಿದೆ.",
  "{branchName} was updated and its Company Code Admin was invited by email.": "{branchName} ಅನ್ನು ನವೀಕರಿಸಲಾಗಿದೆ ಮತ್ತು ಅದರ ಕಂಪನಿ ಕೋಡ್ ಅಡ್ಮಿನ್‌ಗೆ ಇಮೇಲ್ ಮೂಲಕ ಆಹ್ವಾನ ಕಳುಹಿಸಲಾಗಿದೆ.",
  "{branchName} was updated, but assigning its Company Code Admin failed: {reason} — use the Employees page instead.": "{branchName} ಅನ್ನು ನವೀಕರಿಸಲಾಗಿದೆ, ಆದರೆ ಅದರ ಕಂಪನಿ ಕೋಡ್ ಅಡ್ಮಿನ್ ನಿಯೋಜನೆ ವಿಫಲವಾಯಿತು: {reason} — ಬದಲಿಗೆ ಉದ್ಯೋಗಿಗಳ ಪುಟವನ್ನು ಬಳಸಿ.",
  "{branchName} was updated.": "{branchName} ಅನ್ನು ನವೀಕರಿಸಲಾಗಿದೆ.",
  "{stateName} has {matchCount} GST registrations on file — select which one this branch uses.": "{stateName} ನಲ್ಲಿ {matchCount} GST ನೋಂದಣಿಗಳು ದಾಖಲೆಯಲ್ಲಿವೆ — ಈ ಶಾಖೆ ಬಳಸುವುದನ್ನು ಆಯ್ಕೆಮಾಡಿ.",
  "0, 0 is not a real office location. Enter the office coordinates.": "0, 0 ನಿಜವಾದ ಕಚೇರಿ ಸ್ಥಳವಲ್ಲ. ಕಚೇರಿಯ ನಿರ್ದೇಶಾಂಕಗಳನ್ನು ನಮೂದಿಸಿ.",
  "Active Company Codes": "ಸಕ್ರಿಯ ಕಂಪನಿ ಕೋಡ್‌ಗಳು",
  "Add Company Code": "ಕಂಪನಿ ಕೋಡ್ ಸೇರಿಸಿ",
  "Add New Company Code": "ಹೊಸ ಕಂಪನಿ ಕೋಡ್ ಸೇರಿಸಿ",
  "Address is required.": "ವಿಳಾಸ ಅಗತ್ಯವಿದೆ.",
  "Allowed radius is required.": "ಅನುಮತಿಸಿದ ತ್ರಿಜ್ಯ ಅಗತ್ಯವಿದೆ.",
  "Allowed radius must be between 10 and 5000 metres.": "ಅನುಮತಿಸಿದ ತ್ರಿಜ್ಯ 10 ರಿಂದ 5000 ಮೀಟರ್‌ಗಳ ನಡುವೆ ಇರಬೇಕು.",
  "Both latitude and longitude must be provided together.": "ಅಕ್ಷಾಂಶ ಮತ್ತು ರೇಖಾಂಶ ಎರಡನ್ನೂ ಒಟ್ಟಿಗೆ ನೀಡಬೇಕು.",
  "Branch code could not be generated. Try re-selecting the city.": "ಶಾಖೆ ಕೋಡ್ ರಚಿಸಲು ಸಾಧ್ಯವಾಗಲಿಲ್ಲ. ನಗರವನ್ನು ಮತ್ತೆ ಆಯ್ಕೆಮಾಡಲು ಪ್ರಯತ್ನಿಸಿ.",
  "Branch code is still generating, please wait.": "ಶಾಖೆ ಕೋಡ್ ಇನ್ನೂ ರಚನೆಯಾಗುತ್ತಿದೆ, ದಯವಿಟ್ಟು ಕಾಯಿರಿ.",
  "Branch name is required.": "ಶಾಖೆಯ ಹೆಸರು ಅಗತ್ಯವಿದೆ.",
