  "Branch name must be under 200 characters.": "ಶಾಖೆಯ ಹೆಸರು 200 ಅಕ್ಷರಗಳಿಗಿಂತ ಕಡಿಮೆ ಇರಬೇಕು.",
  "Cities Covered": "ಒಳಗೊಂಡ ನಗರಗಳು",
  "City name may only contain letters, spaces, hyphens and apostrophes.": "ನಗರದ ಹೆಸರಿನಲ್ಲಿ ಅಕ್ಷರಗಳು, ಖಾಲಿ ಜಾಗ, ಹೈಫನ್ ಮತ್ತು ಅಪಾಸ್ಟ್ರಫಿ ಮಾತ್ರ ಇರಬಹುದು.",
  "Complete the Company Code Admin details, or clear them to save without an admin.": "ಕಂಪನಿ ಕೋಡ್ ಅಡ್ಮಿನ್ ವಿವರಗಳನ್ನು ಪೂರ್ಣಗೊಳಿಸಿ, ಅಥವಾ ಅಡ್ಮಿನ್ ಇಲ್ಲದೆ ಉಳಿಸಲು ಅವುಗಳನ್ನು ತೆರವುಗೊಳಿಸಿ.",
  "Could not load this Company Code's saved details. Close the form and try again.": "ಈ ಕಂಪನಿ ಕೋಡ್‌ನ ಉಳಿಸಿದ ವಿವರಗಳನ್ನು ಲೋಡ್ ಮಾಡಲು ಸಾಧ್ಯವಾಗಲಿಲ್ಲ. ಫಾರ್ಮ್ ಮುಚ್ಚಿ ಮತ್ತೆ ಪ್ರಯತ್ನಿಸಿ.",
