  "The main office. Only one office can be the headquarter.": "ಮುಖ್ಯ ಕಚೇರಿ. ಒಂದು ಕಚೇರಿ ಮಾತ್ರ ಪ್ರಧಾನ ಕಚೇರಿಯಾಗಿರಬಹುದು.",
