  "No vacant position with branch-wide access. In Org Chart, add a position (or pick a vacant one), open its Permissions and turn on “Branch-wide access”, then come back — or leave this section blank and save.": "ಶಾಖೆಯಾದ್ಯಂತ ಪ್ರವೇಶವಿರುವ ಖಾಲಿ ಹುದ್ದೆ ಇಲ್ಲ. ಸಂಸ್ಥೆ ಚಾರ್ಟ್‌ನಲ್ಲಿ ಹುದ್ದೆಯನ್ನು ಸೇರಿಸಿ (ಅಥವಾ ಖಾಲಿ ಇರುವುದನ್ನು ಆಯ್ಕೆಮಾಡಿ), ಅದರ ಅನುಮತಿಗಳನ್ನು ತೆರೆದು “ಶಾಖೆಯಾದ್ಯಂತ ಪ್ರವೇಶ” ಆನ್ ಮಾಡಿ, ನಂತರ ಹಿಂತಿರುಗಿ — ಅಥವಾ ಈ ವಿಭಾಗವನ್ನು ಖಾಲಿ ಬಿಟ್ಟು ಉಳಿಸಿ.",
  "Search by name, email, or employee ID…": "ಹೆಸರು, ಇಮೇಲ್ ಅಥವಾ ಉದ್ಯೋಗಿ ID ಯಿಂದ ಹುಡುಕಿ…",
