  "Nominees are chosen from this list, and the parents' names on step 1 are filled from it. Add family before setting nominations.": "ನಾಮನಿರ್ದೇಶಿತರನ್ನು ಈ ಪಟ್ಟಿಯಿಂದ ಆಯ್ಕೆ ಮಾಡಲಾಗುತ್ತದೆ ಮತ್ತು ಹಂತ 1 ರಲ್ಲಿನ ಪೋಷಕರ ಹೆಸರುಗಳನ್ನು ಇದರಿಂದಲೇ ಭರ್ತಿ ಮಾಡಲಾಗುತ್ತದೆ. ನಾಮನಿರ್ದೇಶನ ಹೊಂದಿಸುವ ಮೊದಲು ಕುಟುಂಬವನ್ನು ಸೇರಿಸಿ.",
  "Not required of a private employer. Collect only where a government, PSU or aided establishment must report it, or a state incentive scheme requires it. Self-declared, and hidden from reporting managers.": "ಖಾಸಗಿ ಉದ್ಯೋಗದಾತರಿಗೆ ಕಡ್ಡಾಯವಲ್ಲ. ಸರ್ಕಾರಿ, PSU ಅಥವಾ ಅನುದಾನಿತ ಸಂಸ್ಥೆ ವರದಿ ಮಾಡಬೇಕಾದಾಗ ಅಥವಾ ರಾಜ್ಯ ಪ್ರೋತ್ಸಾಹ ಯೋಜನೆಗೆ ಅಗತ್ಯವಿದ್ದಾಗ ಮಾತ್ರ ಸಂಗ್ರಹಿಸಿ. ಸ್ವಯಂ ಘೋಷಣೆ, ಮತ್ತು ವರದಿ ಮಾಡುವ ಮ್ಯಾನೇಜರ್‌ಗಳಿಂದ ಮರೆಮಾಡಲಾಗಿದೆ.",
