  "Monthly amounts use the selected salary structure and effective date. Enabled structure components appear here; statutory contributions and deductions remain governed by payroll eligibility and statutory rules.": "ಮಾಸಿಕ ಮೊತ್ತಗಳು ಆಯ್ಕೆಮಾಡಿದ ವೇತನ ರಚನೆ ಮತ್ತು ಜಾರಿ ದಿನಾಂಕವನ್ನು ಬಳಸುತ್ತವೆ. ಸಕ್ರಿಯಗೊಳಿಸಿದ ರಚನೆಯ ಘಟಕಗಳು ಇಲ್ಲಿ ಕಾಣಿಸುತ್ತವೆ; ಶಾಸನಬದ್ಧ ಕೊಡುಗೆಗಳು ಮತ್ತು ಕಡಿತಗಳು ಪೇರೋಲ್ ಅರ್ಹತೆ ಮತ್ತು ಶಾಸನಬದ್ಧ ನಿಯಮಗಳಿಗೆ ಒಳಪಟ್ಟಿರುತ್ತವೆ.",
  "No pay record exists for this employee yet.": "ಈ ಉದ್ಯೋಗಿಗೆ ಇನ್ನೂ ವೇತನ ದಾಖಲೆ ಇಲ್ಲ.",
  "No salary structure applies to this employee. Add or activate one in Settings → Payroll Configuration → Salary Structures; pay components come from it.": "ಈ ಉದ್ಯೋಗಿಗೆ ಯಾವುದೇ ವೇತನ ರಚನೆ ಅನ್ವಯಿಸುವುದಿಲ್ಲ. ಸೆಟ್ಟಿಂಗ್‌ಗಳು → ಪೇರೋಲ್ ಸಂರಚನೆ → ವೇತನ ರಚನೆಗಳಲ್ಲಿ ಒಂದನ್ನು ಸೇರಿಸಿ ಅಥವಾ ಸಕ್ರಿಯಗೊಳಿಸಿ; ವೇತನ ಘಟಕಗಳು ಅದರಿಂದ ಬರುತ್ತವೆ.",
  "On file — masked": "ದಾಖಲೆಯಲ್ಲಿದೆ — ಮರೆಮಾಡಲಾಗಿದೆ",
