  "Full values are now shown in the Government IDs & Bank card above.": "ಪೂರ್ಣ ಮೌಲ್ಯಗಳನ್ನು ಈಗ ಮೇಲಿನ ಸರ್ಕಾರಿ ID ಗಳು ಮತ್ತು ಬ್ಯಾಂಕ್ ಕಾರ್ಡ್‌ನಲ್ಲಿ ತೋರಿಸಲಾಗಿದೆ.",
  "Government IDs & Bank · Masked": "ಸರ್ಕಾರಿ ID ಗಳು ಮತ್ತು ಬ್ಯಾಂಕ್ · ಮರೆಮಾಡಲಾಗಿದೆ",
