  "No lifecycle events on record yet.": "ಇನ್ನೂ ಯಾವುದೇ ಜೀವನಚಕ್ರ ಘಟನೆಗಳು ದಾಖಲಾಗಿಲ್ಲ.",
  "Non-statutory fields erasable on request; statutory records cannot be deleted early": "ಶಾಸನಬದ್ಧವಲ್ಲದ ಕ್ಷೇತ್ರಗಳನ್ನು ಕೋರಿಕೆಯ ಮೇರೆಗೆ ಅಳಿಸಬಹುದು; ಶಾಸನಬದ್ಧ ದಾಖಲೆಗಳನ್ನು ಬೇಗ ಅಳಿಸಲು ಸಾಧ್ಯವಿಲ್ಲ",
