  "Sensitive Data Control": "ಸೂಕ್ಷ್ಮ ಮಾಹಿತಿ ನಿಯಂತ್ರಣ",
  "This account has no employee record on file (no employee number assigned), so employment, pay, statutory, and history details below are unavailable. This is expected for an admin/system login that was never onboarded as an employee — sign in as an onboarded employee to see a full record.": "ಈ ಖಾತೆಗೆ ಯಾವುದೇ ಉದ್ಯೋಗಿ ದಾಖಲೆ ಇಲ್ಲ (ಉದ್ಯೋಗಿ ಸಂಖ್ಯೆ ನಿಯೋಜಿಸಿಲ್ಲ), ಆದ್ದರಿಂದ ಕೆಳಗಿನ ಉದ್ಯೋಗ, ವೇತನ, ಶಾಸನಬದ್ಧ ಮತ್ತು ಇತಿಹಾಸ ವಿವರಗಳು ಲಭ್ಯವಿಲ್ಲ. ಉದ್ಯೋಗಿಯಾಗಿ ಆನ್‌ಬೋರ್ಡ್ ಆಗದ ಅಡ್ಮಿನ್/ಸಿಸ್ಟಮ್ ಲಾಗಿನ್‌ಗೆ ಇದು ನಿರೀಕ್ಷಿತ — ಪೂರ್ಣ ದಾಖಲೆ ನೋಡಲು ಆನ್‌ಬೋರ್ಡ್ ಆದ ಉದ್ಯೋಗಿಯಾಗಿ ಸೈನ್ ಇನ್ ಮಾಡಿ.",
  "This employee submitted a bank detail change awaiting your review — their previous details remain active for payroll until you decide.": "ಈ ಉದ್ಯೋಗಿ ಬ್ಯಾಂಕ್ ವಿವರ ಬದಲಾವಣೆಯನ್ನು ಸಲ್ಲಿಸಿದ್ದಾರೆ, ನಿಮ್ಮ ಪರಿಶೀಲನೆಗಾಗಿ ಕಾಯುತ್ತಿದೆ — ನೀವು ನಿರ್ಧರಿಸುವವರೆಗೆ ಅವರ ಹಿಂದಿನ ವಿವರಗಳು ಪೇರೋಲ್‌ಗೆ ಸಕ್ರಿಯವಾಗಿರುತ್ತವೆ.",
  "UAN": "UAN",
  "Click to choose the filled .xlsx file": "ಭರ್ತಿ ಮಾಡಿದ .xlsx ಫೈಲ್ ಆಯ್ಕೆಮಾಡಲು ಕ್ಲಿಕ್ ಮಾಡಿ",
  "Confirm import of {count}": "{count} ಆಮದನ್ನು ದೃಢೀಕರಿಸಿ",
  "Confirm.": "ದೃಢೀಕರಿಸಿ.",
  "Download errors (Excel)": "ದೋಷಗಳನ್ನು ಡೌನ್‌ಲೋಡ್ ಮಾಡಿ (Excel)",
  "Download template (.xlsx)": "ಟೆಂಪ್ಲೇಟ್ ಡೌನ್‌ಲೋಡ್ ಮಾಡಿ (.xlsx)",
  "Download the template and fill it in.": "ಟೆಂಪ್ಲೇಟ್ ಡೌನ್‌ಲೋಡ್ ಮಾಡಿ ಮತ್ತು ಭರ್ತಿ ಮಾಡಿ.",
  "Each new employee then gets an activation email.": "ನಂತರ ಪ್ರತಿ ಹೊಸ ಉದ್ಯೋಗಿಗೆ ಸಕ್ರಿಯಗೊಳಿಸುವ ಇಮೇಲ್ ಬರುತ್ತದೆ.",
  "Every row must be valid to start.": "ಪ್ರಾರಂಭಿಸಲು ಪ್ರತಿ ಸಾಲು ಮಾನ್ಯವಾಗಿರಬೇಕು.",
  "Everything is valid. Press Confirm to create these employees.": "ಎಲ್ಲವೂ ಮಾನ್ಯವಾಗಿದೆ. ಈ ಉದ್ಯೋಗಿಗಳನ್ನು ರಚಿಸಲು ದೃಢೀಕರಿಸಿ ಒತ್ತಿ.",
  "Fix the rows below (or download the error file), then upload again. Nothing has been created.": "ಕೆಳಗಿನ ಸಾಲುಗಳನ್ನು ಸರಿಪಡಿಸಿ (ಅಥವಾ ದೋಷ ಫೈಲ್ ಡೌನ್‌ಲೋಡ್ ಮಾಡಿ), ನಂತರ ಮತ್ತೆ ಅಪ್‌ಲೋಡ್ ಮಾಡಿ. ಏನೂ ರಚನೆಯಾಗಿಲ್ಲ.",
  "Import another file": "ಇನ್ನೊಂದು ಫೈಲ್ ಆಮದು ಮಾಡಿ",
  "Import Employees from Excel": "Excel ನಿಂದ ಉದ್ಯೋಗಿಗಳನ್ನು ಆಮದು ಮಾಡಿ",
  "Starting…": "ಪ್ರಾರಂಭಿಸಲಾಗುತ್ತಿದೆ…",
  "The employees are then created in the background, so you can close this window and come back: progress is saved.": "ನಂತರ ಉದ್ಯೋಗಿಗಳನ್ನು ಹಿನ್ನೆಲೆಯಲ್ಲಿ ರಚಿಸಲಾಗುತ್ತದೆ, ಆದ್ದರಿಂದ ನೀವು ಈ ವಿಂಡೋ ಮುಚ್ಚಿ ಮತ್ತೆ ಬರಬಹುದು: ಪ್ರಗತಿಯನ್ನು ಉಳಿಸಲಾಗುತ್ತದೆ.",
