  "Raised by": "ಸಲ್ಲಿಸಿದವರು",
  "Recording a separation ends the current record and starts the exit process. It cannot be reversed — a returning employee needs a fresh Hire action.": "ಸೇವಾ ಮುಕ್ತಾಯವನ್ನು ದಾಖಲಿಸಿದರೆ ಪ್ರಸ್ತುತ ದಾಖಲೆ ಕೊನೆಗೊಂಡು ನಿರ್ಗಮನ ಪ್ರಕ್ರಿಯೆ ಪ್ರಾರಂಭವಾಗುತ್ತದೆ. ಇದನ್ನು ಹಿಂದಿರುಗಿಸಲು ಸಾಧ್ಯವಿಲ್ಲ — ಮರಳಿ ಬರುವ ಉದ್ಯೋಗಿಗೆ ಹೊಸ ನೇಮಕ ಕ್ರಮ ಬೇಕು.",
