  "Could not load that employee.": "ಆ ಉದ್ಯೋಗಿಯನ್ನು ಲೋಡ್ ಮಾಡಲು ಸಾಧ್ಯವಾಗಲಿಲ್ಲ.",
  "Employee hired successfully.": "ಉದ್ಯೋಗಿಯನ್ನು ಯಶಸ್ವಿಯಾಗಿ ನೇಮಿಸಲಾಗಿದೆ.",
  "Activity history": "ಚಟುವಟಿಕೆ ಇತಿಹಾಸ",
  "Every stage change is recorded here with who made it and when.": "ಪ್ರತಿ ಹಂತದ ಬದಲಾವಣೆಯನ್ನು ಯಾರು ಮತ್ತು ಯಾವಾಗ ಮಾಡಿದರು ಎಂಬುದರೊಂದಿಗೆ ಇಲ್ಲಿ ದಾಖಲಿಸಲಾಗುತ್ತದೆ.",
  "Manager notes and calibrated ratings stay hidden until the outcome is published. Publishing an appraisal does not change pay, promotion or any other HR record.": "ಫಲಿತಾಂಶ ಪ್ರಕಟವಾಗುವವರೆಗೆ ಮ್ಯಾನೇಜರ್ ಟಿಪ್ಪಣಿಗಳು ಮತ್ತು ಸಮತೋಲನಗೊಳಿಸಿದ ರೇಟಿಂಗ್‌ಗಳು ಮರೆಯಾಗಿರುತ್ತವೆ. ಮೌಲ್ಯಮಾಪನ ಪ್ರಕಟಿಸುವುದರಿಂದ ವೇತನ, ಪದೋನ್ನತಿ ಅಥವಾ ಬೇರೆ ಯಾವುದೇ HR ದಾಖಲೆ ಬದಲಾಗುವುದಿಲ್ಲ.",
  "No activity recorded yet.": "ಇನ್ನೂ ಯಾವುದೇ ಚಟುವಟಿಕೆ ದಾಖಲಾಗಿಲ್ಲ.",
