  "I have read this appraisal. Acknowledgement does not mean I agree with every rating.": "ನಾನು ಈ ಮೌಲ್ಯಮಾಪನವನ್ನು ಓದಿದ್ದೇನೆ. ಸ್ವೀಕೃತಿ ಎಂದರೆ ಪ್ರತಿಯೊಂದು ರೇಟಿಂಗ್‌ಗೆ ನನ್ನ ಒಪ್ಪಿಗೆ ಇದೆ ಎಂದಲ್ಲ.",
  "Manager assessment and final rating are visible only after HR publication.": "ಮ್ಯಾನೇಜರ್ ಮೌಲ್ಯಮಾಪನ ಮತ್ತು ಅಂತಿಮ ರೇಟಿಂಗ್ HR ಪ್ರಕಟಿಸಿದ ನಂತರವೇ ಕಾಣಿಸುತ್ತವೆ.",
