  "Failed to save. Is there an active review cycle?": "ಉಳಿಸಲು ಸಾಧ್ಯವಾಗಲಿಲ್ಲ. ಸಕ್ರಿಯ ಪರಿಶೀಲನಾ ಚಕ್ರ ಇದೆಯೇ?",
