  "My appraisal": "ನನ್ನ ಮೌಲ್ಯಮಾಪನ",
  "No active review cycle": "ಸಕ್ರಿಯ ಪರಿಶೀಲನಾ ಚಕ್ರ ಇಲ್ಲ",
