  "Once submitted, your self-review answers and ratings are locked and can no longer be edited. Your manager will be notified to complete their review.": "ಸಲ್ಲಿಸಿದ ನಂತರ ನಿಮ್ಮ ಸ್ವಯಂ ಪರಿಶೀಲನೆಯ ಉತ್ತರಗಳು ಮತ್ತು ರೇಟಿಂಗ್‌ಗಳು ಲಾಕ್ ಆಗುತ್ತವೆ ಮತ್ತು ಇನ್ನು ಸಂಪಾದಿಸಲು ಸಾಧ್ಯವಿಲ್ಲ. ಅವರ ಪರಿಶೀಲನೆ ಪೂರ್ಣಗೊಳಿಸಲು ನಿಮ್ಮ ಮ್ಯಾನೇಜರ್‌ಗೆ ತಿಳಿಸಲಾಗುತ್ತದೆ.",
  "Outcome acknowledged.": "ಫಲಿತಾಂಶವನ್ನು ಸ್ವೀಕರಿಸಲಾಗಿದೆ.",
  "Please revise your self-review.": "ದಯವಿಟ್ಟು ನಿಮ್ಮ ಸ್ವಯಂ ಪರಿಶೀಲನೆಯನ್ನು ಪರಿಷ್ಕರಿಸಿ.",
  "Record outcomes against each goal, with evidence that your manager can verify.": "ಪ್ರತಿ ಗುರಿಗೆ ಫಲಿತಾಂಶಗಳನ್ನು ದಾಖಲಿಸಿ, ನಿಮ್ಮ ಮ್ಯಾನೇಜರ್ ಪರಿಶೀಲಿಸಬಹುದಾದ ಪುರಾವೆಗಳೊಂದಿಗೆ.",
  "Returned for changes": "ಬದಲಾವಣೆಗಾಗಿ ಹಿಂತಿರುಗಿಸಲಾಗಿದೆ",
  "Self-review": "ಸ್ವಯಂ ಪರಿಶೀಲನೆ",
  "Self-review submitted.": "ಸ್ವಯಂ ಪರಿಶೀಲನೆ ಸಲ್ಲಿಕೆಯಾಗಿದೆ.",
