  "Your appraisal outcome has been published. Review it below and acknowledge it.": "ನಿಮ್ಮ ಮೌಲ್ಯಮಾಪನ ಫಲಿತಾಂಶವನ್ನು ಪ್ರಕಟಿಸಲಾಗಿದೆ. ಅದನ್ನು ಕೆಳಗೆ ಪರಿಶೀಲಿಸಿ ಮತ್ತು ಸ್ವೀಕರಿಸಿ.",
  "Your self-review has been submitted and can no longer be edited.": "ನಿಮ್ಮ ಸ್ವಯಂ ಪರಿಶೀಲನೆ ಸಲ್ಲಿಕೆಯಾಗಿದೆ ಮತ್ತು ಇನ್ನು ಸಂಪಾದಿಸಲು ಸಾಧ್ಯವಿಲ್ಲ.",
