  "Applying updates the record and resolves this request. Declining needs a reason in the Response box.": "ಅನ್ವಯಿಸಿದರೆ ದಾಖಲೆ ನವೀಕರಣಗೊಂಡು ಈ ವಿನಂತಿ ಪರಿಹಾರವಾಗುತ್ತದೆ. ನಿರಾಕರಿಸಲು ಪ್ರತಿಕ್ರಿಯೆ ಬಾಕ್ಸ್‌ನಲ್ಲಿ ಕಾರಣ ಬೇಕು.",
  "Bank detail: check it against the employee's passbook or a cancelled cheque before applying. The number is shown masked once decided.": "ಬ್ಯಾಂಕ್ ವಿವರ: ಅನ್ವಯಿಸುವ ಮೊದಲು ಉದ್ಯೋಗಿಯ ಪಾಸ್‌ಬುಕ್ ಅಥವಾ ರದ್ದಾದ ಚೆಕ್‌ನೊಂದಿಗೆ ತಾಳೆ ನೋಡಿ. ನಿರ್ಧಾರವಾದ ನಂತರ ಸಂಖ್ಯೆಯನ್ನು ಮರೆಮಾಚಿ ತೋರಿಸಲಾಗುತ್ತದೆ.",
