  "Form 16 will be available after the financial year closes.": "ಹಣಕಾಸು ವರ್ಷ ಮುಗಿದ ನಂತರ ಫಾರ್ಮ್ 16 ಲಭ್ಯವಾಗುತ್ತದೆ.",
  "New": "ಹೊಸ",
  "No submission deadline is configured": "ಸಲ್ಲಿಕೆಗೆ ಯಾವುದೇ ಗಡುವನ್ನು ನಿಗದಿಪಡಿಸಿಲ್ಲ",
