  "Register or update an employee's Face ID in person. It is approved immediately.": "ಉದ್ಯೋಗಿಯ Face ID ಅನ್ನು ವ್ಯಕ್ತಿಗತವಾಗಿ ನೋಂದಾಯಿಸಿ ಅಥವಾ ನವೀಕರಿಸಿ. ಇದು ತಕ್ಷಣ ಅನುಮೋದನೆಯಾಗುತ್ತದೆ.",
