  "Couldn't confirm they're live": "ಅವರು ನೇರವಾಗಿ ಇದ್ದಾರೆ ಎಂದು ದೃಢೀಕರಿಸಲು ಸಾಧ್ಯವಾಗಲಿಲ್ಲ",
  "Downloading face models (first time only)…": "ಮುಖ ಮಾದರಿಗಳನ್ನು ಡೌನ್‌ಲೋಡ್ ಮಾಡಲಾಗುತ್ತಿದೆ (ಮೊದಲ ಬಾರಿ ಮಾತ್ರ)…",
  "Face ID registered!": "Face ID ನೋಂದಾಯಿಸಲಾಗಿದೆ!",
