  "ASSETS": "ಆಸ್ತಿಗಳು",
  "Complete these first: {reasons}": "ಮೊದಲು ಇವುಗಳನ್ನು ಪೂರ್ಣಗೊಳಿಸಿ: {reasons}",
  "DOCUMENTS": "ದಾಖಲೆಗಳು",
  "EDUCATION & EXPERIENCE": "ಶಿಕ್ಷಣ ಮತ್ತು ಅನುಭವ",
  "EMPLOYMENT": "ಉದ್ಯೋಗ",
  "Face ID after hiring": "ನೇಮಕಾತಿಯ ನಂತರ Face ID",
  "Face ID is registered in person by HR. After the hire is created, register it on": "Face ID ಅನ್ನು HR ವ್ಯಕ್ತಿಗತವಾಗಿ ನೋಂದಾಯಿಸುತ್ತದೆ. ನೇಮಕಾತಿ ರಚನೆಯಾದ ನಂತರ ಅದನ್ನು ಇಲ್ಲಿ ನೋಂದಾಯಿಸಿ:",
