  "Not payroll ready": "ಪೇರೋಲ್‌ಗೆ ಸಿದ್ಧವಿಲ್ಲ",
  "Not ready to hire — complete these first": "ನೇಮಿಸಲು ಸಿದ್ಧವಿಲ್ಲ — ಮೊದಲು ಇವುಗಳನ್ನು ಪೂರ್ಣಗೊಳಿಸಿ",
  "Old Regime": "ಹಳೆಯ ವ್ಯವಸ್ಥೆ",
  "PERSONAL": "ವೈಯಕ್ತಿಕ",
  "Ready to hire": "ನೇಮಿಸಲು ಸಿದ್ಧ",
  "Record completeness": "ದಾಖಲೆಯ ಪೂರ್ಣತೆ",
  "STATUTORY & ACCOUNTS": "ಕಾನೂನುಬದ್ಧ ಮತ್ತು ಖಾತೆಗಳು",
  "The new hire cannot register it themselves.": "ಹೊಸ ಉದ್ಯೋಗಿ ಅದನ್ನು ತಾವೇ ನೋಂದಾಯಿಸಲು ಸಾಧ್ಯವಿಲ್ಲ.",
  "The new hire registers their Face ID from their Profile page, and HR approves it on": "ಹೊಸ ಉದ್ಯೋಗಿ ತಮ್ಮ ಪ್ರೊಫೈಲ್ ಪುಟದಿಂದ Face ID ನೋಂದಾಯಿಸುತ್ತಾರೆ, ಮತ್ತು HR ಅದನ್ನು ಇಲ್ಲಿ ಅನುಮೋದಿಸುತ್ತದೆ:",
  "The new hire registers their own Face ID from their Profile page; it is active immediately.": "ಹೊಸ ಉದ್ಯೋಗಿ ತಮ್ಮ ಪ್ರೊಫೈಲ್ ಪುಟದಿಂದ ತಮ್ಮದೇ Face ID ನೋಂದಾಯಿಸುತ್ತಾರೆ; ಅದು ತಕ್ಷಣ ಸಕ್ರಿಯವಾಗುತ್ತದೆ.",
  "the record can still be created in Onboarding status.": "ದಾಖಲೆಯನ್ನು ಆನ್‌ಬೋರ್ಡಿಂಗ್ ಸ್ಥಿತಿಯಲ್ಲಿ ಇನ್ನೂ ರಚಿಸಬಹುದು.",
  "The record is created in Onboarding status. Optional details (father/mother's name, non-required documents) can still be finished afterward.": "ದಾಖಲೆಯನ್ನು ಆನ್‌ಬೋರ್ಡಿಂಗ್ ಸ್ಥಿತಿಯಲ್ಲಿ ರಚಿಸಲಾಗುತ್ತದೆ. ಐಚ್ಛಿಕ ವಿವರಗಳನ್ನು (ತಂದೆ/ತಾಯಿಯ ಹೆಸರು, ಅಗತ್ಯವಿಲ್ಲದ ದಾಖಲೆಗಳು) ನಂತರವೂ ಪೂರ್ಣಗೊಳಿಸಬಹುದು.",
  "Until it is done they cannot clock in on the web.": "ಅದು ಆಗುವವರೆಗೆ ಅವರು ವೆಬ್‌ನಲ್ಲಿ ಕ್ಲಾಕ್ ಇನ್ ಮಾಡಲು ಸಾಧ್ಯವಿಲ್ಲ.",
  "Until then they can still clock in from the office; those punches are flagged for HR.": "ಅಲ್ಲಿಯವರೆಗೆ ಅವರು ಕಚೇರಿಯಿಂದ ಕ್ಲಾಕ್ ಇನ್ ಮಾಡಬಹುದು; ಆ ಪಂಚ್‌ಗಳನ್ನು HR ಗಾಗಿ ಗುರುತಿಸಲಾಗುತ್ತದೆ.",
  "Apply selected": "ಆಯ್ದವುಗಳನ್ನು ಅನ್ವಯಿಸಿ",
  "Choose a PDF, JPG or PNG": "PDF, JPG ಅಥವಾ PNG ಆಯ್ಕೆಮಾಡಿ",
  "Could not scan this document. Please try again.": "ಈ ದಾಖಲೆಯನ್ನು ಸ್ಕ್ಯಾನ್ ಮಾಡಲು ಸಾಧ್ಯವಾಗಲಿಲ್ಲ. ದಯವಿಟ್ಟು ಮತ್ತೆ ಪ್ರಯತ್ನಿಸಿ.",
  "FOUND IN DOCUMENT": "ದಾಖಲೆಯಲ್ಲಿ ಕಂಡುಬಂದದ್ದು",
  "Scanning…": "ಸ್ಕ್ಯಾನ್ ಮಾಡಲಾಗುತ್ತಿದೆ…",
  "Upload a text-based PDF (an offer letter, ID or resume exported as PDF). This reads the actual text in the document and matches recognizable fields — it does not guess anything not on the page.": "ಪಠ್ಯ ಆಧಾರಿತ PDF ಅಪ್‌ಲೋಡ್ ಮಾಡಿ (PDF ಆಗಿ ರಫ್ತು ಮಾಡಿದ ಆಫರ್ ಲೆಟರ್, ಐಡಿ ಅಥವಾ ರೆಸ್ಯೂಮ್). ಇದು ದಾಖಲೆಯಲ್ಲಿರುವ ನಿಜವಾದ ಪಠ್ಯವನ್ನು ಓದಿ ಗುರುತಿಸಬಹುದಾದ ಕ್ಷೇತ್ರಗಳನ್ನು ಹೊಂದಿಸುತ್ತದೆ — ಪುಟದಲ್ಲಿ ಇಲ್ಲದ ಯಾವುದನ್ನೂ ಊಹಿಸುವುದಿಲ್ಲ.",
  "10 digits, if available": "10 ಅಂಕೆಗಳು, ಲಭ್ಯವಿದ್ದರೆ",
