  "Auto-filled from IFSC, or enter manually": "IFSC ಯಿಂದ ಸ್ವಯಂ ಭರ್ತಿಯಾಗುತ್ತದೆ, ಅಥವಾ ಕೈಯಿಂದ ನಮೂದಿಸಿ",
  "BANK ACCOUNT": "ಬ್ಯಾಂಕ್ ಖಾತೆ",
  "Bank and branch found — filled in below.": "ಬ್ಯಾಂಕ್ ಮತ್ತು ಶಾಖೆ ಕಂಡುಬಂದಿದೆ — ಕೆಳಗೆ ಭರ್ತಿ ಮಾಡಲಾಗಿದೆ.",
