  "Move candidates through the stages. Selected candidates receive the nine-step self-service onboarding wizard; direct hires use the HR hiring form and skip it.": "ಅಭ್ಯರ್ಥಿಗಳನ್ನು ಹಂತಗಳ ಮೂಲಕ ಮುಂದೆ ಸಾಗಿಸಿ. ಆಯ್ಕೆಯಾದ ಅಭ್ಯರ್ಥಿಗಳು ಒಂಬತ್ತು ಹಂತಗಳ ಸ್ವಯಂ ಸೇವಾ ಆನ್‌ಬೋರ್ಡಿಂಗ್ ವಿಝಾರ್ಡ್ ಪಡೆಯುತ್ತಾರೆ; ನೇರ ನೇಮಕಾತಿಗಳು HR ನೇಮಕಾತಿ ಫಾರ್ಮ್ ಬಳಸುತ್ತವೆ ಮತ್ತು ಅದನ್ನು ಬಿಟ್ಟುಬಿಡುತ್ತವೆ.",
