  "No interviewer has submitted feedback yet. A candidate cannot be marked Selected until at least one has.": "ಇನ್ನೂ ಯಾವ ಸಂದರ್ಶಕರೂ ಪ್ರತಿಕ್ರಿಯೆ ಸಲ್ಲಿಸಿಲ್ಲ. ಕನಿಷ್ಠ ಒಬ್ಬರು ಸಲ್ಲಿಸುವವರೆಗೆ ಅಭ್ಯರ್ಥಿಯನ್ನು ಆಯ್ಕೆ ಎಂದು ಗುರುತಿಸಲು ಸಾಧ್ಯವಿಲ್ಲ.",
