  "Send onboarding link?": "ಆನ್‌ಬೋರ್ಡಿಂಗ್ ಲಿಂಕ್ ಕಳುಹಿಸಬೇಕೇ?",
  "This emails {name} ({email}) a one-time link, valid for a limited time, to complete the onboarding wizard and upload documents. No account or password is created until you approve the onboarding.": "ಇದು {name} ({email}) ಅವರಿಗೆ ಆನ್‌ಬೋರ್ಡಿಂಗ್ ವಿಝಾರ್ಡ್ ಪೂರ್ಣಗೊಳಿಸಲು ಮತ್ತು ದಾಖಲೆಗಳನ್ನು ಅಪ್‌ಲೋಡ್ ಮಾಡಲು ಸೀಮಿತ ಅವಧಿಗೆ ಮಾನ್ಯವಾದ ಒಂದು ಬಾರಿಯ ಲಿಂಕ್ ಅನ್ನು ಇಮೇಲ್ ಮಾಡುತ್ತದೆ. ನೀವು ಆನ್‌ಬೋರ್ಡಿಂಗ್ ಅನ್ನು ಅನುಮೋದಿಸುವವರೆಗೆ ಯಾವುದೇ ಖಾತೆ ಅಥವಾ ಪಾಸ್‌ವರ್ಡ್ ರಚನೆಯಾಗುವುದಿಲ್ಲ.",
