  "End date is required.": "ಅಂತಿಮ ದಿನಾಂಕ ಅಗತ್ಯ.",
  "End date must be on or after start date.": "ಅಂತಿಮ ದಿನಾಂಕ ಆರಂಭ ದಿನಾಂಕದಂದು ಅಥವಾ ಅದರ ನಂತರ ಇರಬೇಕು.",
