  "Failed to assign holder.": "ಹುದ್ದೆ ಹೊಂದಿರುವವರನ್ನು ನಿಯೋಜಿಸಲು ಸಾಧ್ಯವಾಗಲಿಲ್ಲ.",
  "Pick an employee.": "ಉದ್ಯೋಗಿಯನ್ನು ಆರಿಸಿ.",
  "Placing a person on a chief position makes them the unit's head automatically, as of the effective date above. A future-dated start schedules the change without affecting today's holder.": "ಮುಖ್ಯ ಹುದ್ದೆಗೆ ವ್ಯಕ್ತಿಯನ್ನು ನಿಯೋಜಿಸಿದರೆ ಮೇಲಿನ ಜಾರಿ ದಿನಾಂಕದಿಂದ ಅವರು ಸ್ವಯಂಚಾಲಿತವಾಗಿ ಘಟಕದ ಮುಖ್ಯಸ್ಥರಾಗುತ್ತಾರೆ. ಭವಿಷ್ಯದ ದಿನಾಂಕದ ಆರಂಭವು ಇಂದಿನ ಹುದ್ದೆದಾರರ ಮೇಲೆ ಪರಿಣಾಮ ಬೀರದೆ ಬದಲಾವಣೆಯನ್ನು ನಿಗದಿಪಡಿಸುತ್ತದೆ.",
  "Reassign": "ಮರುನಿಯೋಜಿಸಿ",
  "Reassign holder": "ಹುದ್ದೆ ಹೊಂದಿರುವವರನ್ನು ಮರುನಿಯೋಜಿಸಿ",
  "Select an employee…": "ಉದ್ಯೋಗಿಯನ್ನು ಆಯ್ಕೆಮಾಡಿ…",
  " — nothing is deleted, and this can be reversed at any time.": " — ಏನನ್ನೂ ಅಳಿಸಲಾಗುವುದಿಲ್ಲ, ಮತ್ತು ಇದನ್ನು ಯಾವಾಗ ಬೇಕಾದರೂ ಹಿಂತಿರುಗಿಸಬಹುದು.",
  ". Deactivating it does": ". ಇದನ್ನು ನಿಷ್ಕ್ರಿಯಗೊಳಿಸುವುದರಿಂದ",
  ". Vacate it first if that's what you actually want.": ". ನಿಮಗೆ ನಿಜವಾಗಿಯೂ ಬೇಕಾಗಿರುವುದು ಅದೇ ಆಗಿದ್ದರೆ ಮೊದಲು ಅದನ್ನು ಖಾಲಿ ಮಾಡಿ.",
  "chief": "ಮುಖ್ಯ",
  "Deactivate position": "ಹುದ್ದೆಯನ್ನು ನಿಷ್ಕ್ರಿಯಗೊಳಿಸಿ",
  "Deactivated positions keep their full placement history and stay visible in the tree, tagged": "ನಿಷ್ಕ್ರಿಯಗೊಳಿಸಿದ ಹುದ್ದೆಗಳು ತಮ್ಮ ಪೂರ್ಣ ನಿಯೋಜನೆ ಇತಿಹಾಸವನ್ನು ಉಳಿಸಿಕೊಳ್ಳುತ್ತವೆ ಮತ್ತು ಮರದಲ್ಲಿ ಕಾಣಿಸುತ್ತವೆ, ಈ ಟ್ಯಾಗ್‌ನೊಂದಿಗೆ:",
  "end their placement or vacate the seat — the position will just show as": "ಅವರ ನಿಯೋಜನೆಯನ್ನು ಕೊನೆಗೊಳಿಸುವುದಿಲ್ಲ ಅಥವಾ ಹುದ್ದೆಯನ್ನು ಖಾಲಿ ಮಾಡುವುದಿಲ್ಲ — ಹುದ್ದೆ ಕೇವಲ ಹೀಗೆ ಕಾಣಿಸುತ್ತದೆ:",
  "Failed to deactivate this position.": "ಈ ಹುದ್ದೆಯನ್ನು ನಿಷ್ಕ್ರಿಯಗೊಳಿಸಲು ಸಾಧ್ಯವಾಗಲಿಲ್ಲ.",
  "not": "ಇಲ್ಲ",
  "position for {unit}. Deactivating it leaves the unit without a visible head until another position is marked chief.": "{unit} ಗಾಗಿ ಹುದ್ದೆ. ಇದನ್ನು ನಿಷ್ಕ್ರಿಯಗೊಳಿಸಿದರೆ ಮತ್ತೊಂದು ಹುದ್ದೆಯನ್ನು ಮುಖ್ಯ ಎಂದು ಗುರುತಿಸುವವರೆಗೆ ಘಟಕಕ್ಕೆ ಕಾಣಿಸುವ ಮುಖ್ಯಸ್ಥರು ಇರುವುದಿಲ್ಲ.",
  "This is the": "ಇದು",
  "This position currently has an active holder,": "ಈ ಹುದ್ದೆಗೆ ಪ್ರಸ್ತುತ ಸಕ್ರಿಯ ಹುದ್ದೆದಾರರಿದ್ದಾರೆ,",
  "{name} stays the holder through this date. The seat becomes vacant the day after.": "{name} ಈ ದಿನಾಂಕದವರೆಗೆ ಹುದ್ದೆದಾರರಾಗಿರುತ್ತಾರೆ. ಮರುದಿನ ಹುದ್ದೆ ಖಾಲಿಯಾಗುತ್ತದೆ.",
  "Can't be before {date}, when this placement started.": "ಈ ನಿಯೋಜನೆ ಪ್ರಾರಂಭವಾದ {date} ಕ್ಕಿಂತ ಮೊದಲು ಇರಬಾರದು.",
