  "Permanently delete \"{name}\"? This can't be undone, and only works if it has never had a holder — if it has any placement history, this will be rejected; deactivate it instead.": "\"{name}\" ಅನ್ನು ಶಾಶ್ವತವಾಗಿ ಅಳಿಸಬೇಕೇ? ಇದನ್ನು ಹಿಂದಕ್ಕೆ ಪಡೆಯಲು ಸಾಧ್ಯವಿಲ್ಲ, ಮತ್ತು ಇದಕ್ಕೆ ಎಂದಿಗೂ ಹುದ್ದೆದಾರರಿಲ್ಲದಿದ್ದರೆ ಮಾತ್ರ ಕೆಲಸ ಮಾಡುತ್ತದೆ — ಯಾವುದೇ ನಿಯೋಜನೆ ಇತಿಹಾಸವಿದ್ದರೆ ಇದನ್ನು ತಿರಸ್ಕರಿಸಲಾಗುತ್ತದೆ; ಬದಲಿಗೆ ನಿಷ್ಕ್ರಿಯಗೊಳಿಸಿ.",
  "Permanently delete \"{name}\"? This can't be undone, and only works if none of its positions have ever been held by anyone — if any have, this will be rejected; deactivate the unit instead.": "\"{name}\" ಅನ್ನು ಶಾಶ್ವತವಾಗಿ ಅಳಿಸಬೇಕೇ? ಇದನ್ನು ಹಿಂದಕ್ಕೆ ಪಡೆಯಲು ಸಾಧ್ಯವಿಲ್ಲ, ಮತ್ತು ಅದರ ಯಾವ ಹುದ್ದೆಯನ್ನೂ ಎಂದಿಗೂ ಯಾರೂ ಹೊಂದಿಲ್ಲದಿದ್ದರೆ ಮಾತ್ರ ಕೆಲಸ ಮಾಡುತ್ತದೆ — ಹೊಂದಿದ್ದರೆ ಇದನ್ನು ತಿರಸ್ಕರಿಸಲಾಗುತ್ತದೆ; ಬದಲಿಗೆ ಘಟಕವನ್ನು ನಿಷ್ಕ್ರಿಯಗೊಳಿಸಿ.",
