  "Positions with nobody reporting to them and no one they report to. Set 'Reports to' on a position to place it in the chain.": "ತಮಗೆ ಯಾರೂ ವರದಿ ಮಾಡದ ಮತ್ತು ತಾವು ಯಾರಿಗೂ ವರದಿ ಮಾಡದ ಹುದ್ದೆಗಳು. ಹುದ್ದೆಯನ್ನು ಸರಪಳಿಯಲ್ಲಿ ಇರಿಸಲು ಅದರಲ್ಲಿ 'ವರದಿ ಮಾಡುವುದು' ಹೊಂದಿಸಿ.",
  "Show {count} direct report": "{count} ನೇರ ವರದಿದಾರರನ್ನು ತೋರಿಸಿ",
