  "Show reports": "ವರದಿ ಮಾಡುವವರನ್ನು ತೋರಿಸಿ",
  ", not a person. You mark one position in each unit as": ", ವ್ಯಕ್ತಿಯಲ್ಲ. ನೀವು ಪ್ರತಿ ಘಟಕದಲ್ಲಿ ಒಂದು ಹುದ್ದೆಯನ್ನು ಹೀಗೆ ಗುರುತಿಸುತ್ತೀರಿ:",
  "; whoever holds it is the head. The seat can stay": "; ಅದನ್ನು ಹೊಂದಿರುವವರು ಮುಖ್ಯಸ್ಥರಾಗುತ್ತಾರೆ. ಈ ಹುದ್ದೆ ಹೀಗೆಯೇ ಉಳಿಯಬಹುದು:",
  ". Access belongs to that seat—not the reporting chain; employees sharing a seat share its permissions. Use separate positions when employees need different access.": ". ಪ್ರವೇಶ ಆ ಹುದ್ದೆಗೆ ಸೇರಿದ್ದು—ವರದಿ ಸರಪಳಿಗಲ್ಲ; ಒಂದೇ ಹುದ್ದೆಯನ್ನು ಹಂಚಿಕೊಳ್ಳುವ ಉದ್ಯೋಗಿಗಳು ಅದರ ಅನುಮತಿಗಳನ್ನು ಹಂಚಿಕೊಳ್ಳುತ್ತಾರೆ. ಉದ್ಯೋಗಿಗಳಿಗೆ ಬೇರೆ ಬೇರೆ ಪ್ರವೇಶ ಬೇಕಾದರೆ ಪ್ರತ್ಯೇಕ ಹುದ್ದೆಗಳನ್ನು ಬಳಸಿ.",
