  "One box per position, joined by who it reports to · click a box for details": "ಪ್ರತಿ ಹುದ್ದೆಗೆ ಒಂದು ಬಾಕ್ಸ್, ಅದು ಯಾರಿಗೆ ವರದಿ ಮಾಡುತ್ತದೆ ಎಂಬುದರ ಪ್ರಕಾರ ಜೋಡಣೆ · ವಿವರಗಳಿಗಾಗಿ ಬಾಕ್ಸ್ ಕ್ಲಿಕ್ ಮಾಡಿ",
  "Org Units": "ಸಂಸ್ಥೆ ಘಟಕಗಳು",
