  "Org units, the positions inside them, and who holds each seat. Modeled on positions, so structure exists before anyone is hired.": "ಸಂಸ್ಥೆ ಘಟಕಗಳು, ಅವುಗಳೊಳಗಿನ ಹುದ್ದೆಗಳು ಮತ್ತು ಪ್ರತಿ ಹುದ್ದೆಯನ್ನು ಯಾರು ಹೊಂದಿದ್ದಾರೆ. ಹುದ್ದೆಗಳ ಆಧಾರದ ಮೇಲೆ ರೂಪಿಸಲಾಗಿದೆ, ಆದ್ದರಿಂದ ಯಾರನ್ನೂ ನೇಮಿಸುವ ಮೊದಲೇ ರಚನೆ ಇರುತ್ತದೆ.",
