  "No payslips found. Employees may be missing CTC or salary structure.": "ಯಾವುದೇ ವೇತನ ಚೀಟಿಗಳು ಕಂಡುಬಂದಿಲ್ಲ. ಉದ್ಯೋಗಿಗಳಿಗೆ CTC ಅಥವಾ ವೇತನ ರಚನೆ ಇಲ್ಲದಿರಬಹುದು.",
