  "Set up their salary in Employees → Salary tab, then reprocess to include them.": "ಉದ್ಯೋಗಿಗಳು → ವೇತನ ಟ್ಯಾಬ್‌ನಲ್ಲಿ ಅವರ ವೇತನವನ್ನು ಹೊಂದಿಸಿ, ನಂತರ ಅವರನ್ನು ಸೇರಿಸಲು ಮರುಪ್ರಕ್ರಿಯೆ ಮಾಡಿ.",
  "Spl. Allow.": "ವಿಶೇಷ ಭತ್ಯೆ",
  "Statutory Deductions": "ಕಾನೂನುಬದ್ಧ ಕಡಿತಗಳು",
  "This recalculates salaries for all {count} employee in this cycle from scratch, overwriting the current figures — including any manual bonus or reimbursement adjustments already made on these payslips. This cannot be undone.": "ಇದು ಈ ಅವಧಿಯ ಎಲ್ಲಾ {count} ಉದ್ಯೋಗಿಯ ವೇತನವನ್ನು ಮೊದಲಿನಿಂದ ಮರುಲೆಕ್ಕಾಚಾರ ಮಾಡಿ, ಪ್ರಸ್ತುತ ಅಂಕಿಅಂಶಗಳನ್ನು ಬದಲಿಸುತ್ತದೆ — ಈ ವೇತನ ಚೀಟಿಗಳಲ್ಲಿ ಈಗಾಗಲೇ ಮಾಡಿದ ಕೈಯಾರೆ ಬೋನಸ್ ಅಥವಾ ಮರುಪಾವತಿ ಹೊಂದಾಣಿಕೆಗಳು ಸೇರಿದಂತೆ. ಇದನ್ನು ಹಿಂತಿರುಗಿಸಲು ಸಾಧ್ಯವಿಲ್ಲ.",
  "This recalculates salaries for all {count} employees in this cycle from scratch, overwriting the current figures — including any manual bonus or reimbursement adjustments already made on these payslips. This cannot be undone.": "ಇದು ಈ ಅವಧಿಯ ಎಲ್ಲಾ {count} ಉದ್ಯೋಗಿಗಳ ವೇತನವನ್ನು ಮೊದಲಿನಿಂದ ಮರುಲೆಕ್ಕಾಚಾರ ಮಾಡಿ, ಪ್ರಸ್ತುತ ಅಂಕಿಅಂಶಗಳನ್ನು ಬದಲಿಸುತ್ತದೆ — ಈ ವೇತನ ಚೀಟಿಗಳಲ್ಲಿ ಈಗಾಗಲೇ ಮಾಡಿದ ಕೈಯಾರೆ ಬೋನಸ್ ಅಥವಾ ಮರುಪಾವತಿ ಹೊಂದಾಣಿಕೆಗಳು ಸೇರಿದಂತೆ. ಇದನ್ನು ಹಿಂತಿರುಗಿಸಲು ಸಾಧ್ಯವಿಲ್ಲ.",
  "This will calculate salaries for all eligible employees using their CTC, salary structure, and statutory rules for each branch.": "ಇದು ಅರ್ಹ ಎಲ್ಲಾ ಉದ್ಯೋಗಿಗಳ CTC, ವೇತನ ರಚನೆ ಮತ್ತು ಪ್ರತಿ ಶಾಖೆಯ ಕಾನೂನುಬದ್ಧ ನಿಯಮಗಳ ಆಧಾರದ ಮೇಲೆ ವೇತನಗಳನ್ನು ಲೆಕ್ಕಾಚಾರ ಮಾಡುತ್ತದೆ.",
