  "Gross/net payroll trends, department breakdowns, and overtime cost charts will be available once dedicated analytics endpoints are built. The data above is computed live from your payroll cycle records.": "ಒಟ್ಟು/ನಿವ್ವಳ ಪೇರೋಲ್ ಪ್ರವೃತ್ತಿಗಳು, ವಿಭಾಗವಾರು ವಿವರಗಳು ಮತ್ತು ಓವರ್‌ಟೈಮ್ ವೆಚ್ಚದ ಚಾರ್ಟ್‌ಗಳು ಮೀಸಲಾದ ವಿಶ್ಲೇಷಣಾ ಸೌಲಭ್ಯಗಳು ಸಿದ್ಧವಾದ ನಂತರ ಲಭ್ಯವಾಗುತ್ತವೆ. ಮೇಲಿನ ಡೇಟಾವನ್ನು ನಿಮ್ಮ ಪೇರೋಲ್ ಅವಧಿ ದಾಖಲೆಗಳಿಂದ ನೇರವಾಗಿ ಲೆಕ್ಕಾಚಾರ ಮಾಡಲಾಗಿದೆ.",
