  "Run Payroll — {branch}": "ಪೇರೋಲ್ ರನ್ ಮಾಡಿ — {branch}",
  "Your account is not assigned to a branch. Payroll actions are unavailable until an administrator assigns you to a branch in Settings → Employees.": "ನಿಮ್ಮ ಖಾತೆಯನ್ನು ಯಾವುದೇ ಶಾಖೆಗೆ ನಿಯೋಜಿಸಿಲ್ಲ. ಅಡ್ಮಿನಿಸ್ಟ್ರೇಟರ್ ಸೆಟ್ಟಿಂಗ್‌ಗಳು → ಉದ್ಯೋಗಿಗಳಲ್ಲಿ ನಿಮ್ಮನ್ನು ಶಾಖೆಗೆ ನಿಯೋಜಿಸುವವರೆಗೆ ಪೇರೋಲ್ ಕ್ರಮಗಳು ಲಭ್ಯವಿಲ್ಲ.",
  "Computed Period Dates": "ಲೆಕ್ಕಾಚಾರದ ಅವಧಿ ದಿನಾಂಕಗಳು",
  "Dates are auto-filled from your Payroll Run Settings. Adjust month/year to change them.": "ದಿನಾಂಕಗಳನ್ನು ನಿಮ್ಮ ಪೇರೋಲ್ ರನ್ ಸೆಟ್ಟಿಂಗ್‌ಗಳಿಂದ ತಾನಾಗಿ ತುಂಬಲಾಗಿದೆ. ಅವುಗಳನ್ನು ಬದಲಿಸಲು ತಿಂಗಳು/ವರ್ಷ ಸರಿಹೊಂದಿಸಿ.",
  "e.g. June 2026 regular payroll run": "ಉದಾ. ಜೂನ್ 2026 ನಿಯಮಿತ ಪೇರೋಲ್ ರನ್",
