  "Payroll Month *": "ಪೇರೋಲ್ ತಿಂಗಳು *",
  "Payroll Period Setup": "ಪೇರೋಲ್ ಅವಧಿ ಸೆಟಪ್",
  "Payroll settings not configured — dates default to month boundaries. Go to Settings → Payroll Configuration to set custom days.": "ಪೇರೋಲ್ ಸೆಟ್ಟಿಂಗ್‌ಗಳನ್ನು ಹೊಂದಿಸಿಲ್ಲ — ದಿನಾಂಕಗಳು ತಿಂಗಳ ಗಡಿಗಳಿಗೆ ಡೀಫಾಲ್ಟ್ ಆಗುತ್ತವೆ. ಕಸ್ಟಮ್ ದಿನಗಳನ್ನು ಹೊಂದಿಸಲು ಸೆಟ್ಟಿಂಗ್‌ಗಳು → ಪೇರೋಲ್ ಕಾನ್ಫಿಗರೇಶನ್‌ಗೆ ಹೋಗಿ.",
