  "All Periods": "ಎಲ್ಲಾ ಅವಧಿಗಳು",
  "ECR (Electronic Challan-cum-Return)": "ECR (ಎಲೆಕ್ಟ್ರಾನಿಕ್ ಚಲನ್-ಕಮ್-ರಿಟರ್ನ್)",
  "ECR export is available after a payroll cycle is completed and payslips are dispatched. Complete a payroll run first.": "ಪೇರೋಲ್ ಅವಧಿ ಪೂರ್ಣಗೊಂಡು ವೇತನ ಚೀಟಿಗಳನ್ನು ರವಾನಿಸಿದ ನಂತರ ECR ರಫ್ತು ಲಭ್ಯವಾಗುತ್ತದೆ. ಮೊದಲು ಪೇರೋಲ್ ರನ್ ಪೂರ್ಣಗೊಳಿಸಿ.",
  "ECR is only available once payslips have been generated for this period.": "ಈ ಅವಧಿಗೆ ವೇತನ ಚೀಟಿಗಳನ್ನು ರಚಿಸಿದ ನಂತರವೇ ECR ಲಭ್ಯವಾಗುತ್ತದೆ.",
  "Excel": "Excel",
