  "No payroll cycles yet. Run your first payroll to enable ECR export.": "ಇನ್ನೂ ಯಾವುದೇ ಪೇರೋಲ್ ಅವಧಿಗಳಿಲ್ಲ. ECR ರಫ್ತು ಸಕ್ರಿಯಗೊಳಿಸಲು ನಿಮ್ಮ ಮೊದಲ ಪೇರೋಲ್ ರನ್ ಮಾಡಿ.",
