  "All payslips dispatched. Employees have until {date} to raise queries.": "ಎಲ್ಲಾ ವೇತನ ಚೀಟಿಗಳನ್ನು ರವಾನಿಸಲಾಗಿದೆ. ಪ್ರಶ್ನೆಗಳನ್ನು ಎತ್ತಲು ಉದ್ಯೋಗಿಗಳಿಗೆ {date} ವರೆಗೆ ಸಮಯವಿದೆ.",
