  "This will email payslips to all {count} employee in this cycle (total net pay {amount}). Employees will be able to view and query them immediately. This cannot be undone.": "ಇದು ಈ ಅವಧಿಯ ಎಲ್ಲಾ {count} ಉದ್ಯೋಗಿಗೆ ವೇತನ ಚೀಟಿಗಳನ್ನು ಇಮೇಲ್ ಮಾಡುತ್ತದೆ (ಒಟ್ಟು ನಿವ್ವಳ ವೇತನ {amount}). ಉದ್ಯೋಗಿಗಳು ಅವುಗಳನ್ನು ತಕ್ಷಣ ವೀಕ್ಷಿಸಬಹುದು ಮತ್ತು ಪ್ರಶ್ನಿಸಬಹುದು. ಇದನ್ನು ಹಿಂತಿರುಗಿಸಲು ಸಾಧ್ಯವಿಲ್ಲ.",
