  "{count} employee(s) have more than 15 LOP days. Verify this is correct before proceeding.": "{count} ಉದ್ಯೋಗಿ(ಗಳಿಗೆ) 15 ಕ್ಕಿಂತ ಹೆಚ್ಚು LOP ದಿನಗಳಿವೆ. ಮುಂದುವರಿಯುವ ಮೊದಲು ಇದು ಸರಿಯಾಗಿದೆಯೇ ಎಂದು ಪರಿಶೀಲಿಸಿ.",
