  "{count} employee(s) have zero gross earnings. Check that their CTC and salary structure are configured correctly.": "{count} ಉದ್ಯೋಗಿ(ಗಳಿಗೆ) ಒಟ್ಟು ಗಳಿಕೆ ಶೂನ್ಯವಾಗಿದೆ. ಅವರ CTC ಮತ್ತು ವೇತನ ರಚನೆ ಸರಿಯಾಗಿ ಹೊಂದಿಸಲಾಗಿದೆಯೇ ಎಂದು ಪರಿಶೀಲಿಸಿ.",
