  "Comment": "ಕಾಮೆಂಟ್",
  "This request will be rejected and the workflow will stop here.": "ಈ ವಿನಂತಿಯನ್ನು ತಿರಸ್ಕರಿಸಲಾಗುತ್ತದೆ ಮತ್ತು ಕಾರ್ಯವಿಧಾನ ಇಲ್ಲಿಗೆ ನಿಲ್ಲುತ್ತದೆ.",
