  "{count} earned leave day(s)": "{count} ಗಳಿಕೆ ರಜೆ ದಿನ(ಗಳು)",
  "{served} of {required} days served ({short} short). A recovery of {amount} has been calculated. Confirm with HR or finance whether this recovery applies before finalising.": "{required} ದಿನಗಳಲ್ಲಿ {served} ದಿನ ಸೇವೆ ಸಲ್ಲಿಸಲಾಗಿದೆ ({short} ಕಡಿಮೆ). {amount} ವಸೂಲಿಯನ್ನು ಲೆಕ್ಕಾಚಾರ ಮಾಡಲಾಗಿದೆ. ಅಂತಿಮಗೊಳಿಸುವ ಮೊದಲು ಈ ವಸೂಲಿ ಅನ್ವಯಿಸುತ್ತದೆಯೇ ಎಂದು HR ಅಥವಾ ಹಣಕಾಸು ವಿಭಾಗದೊಂದಿಗೆ ದೃಢಪಡಿಸಿ.",
  "{served}/{required} days served — {short} day shortfall": "{served}/{required} ದಿನ ಸೇವೆ ಸಲ್ಲಿಸಲಾಗಿದೆ — {short} ದಿನ ಕೊರತೆ",
  "Deductions exceed earnings — this amount is owed back by the employee, not paid to them.": "ಕಡಿತಗಳು ಗಳಿಕೆಯನ್ನು ಮೀರಿವೆ — ಈ ಮೊತ್ತವನ್ನು ಉದ್ಯೋಗಿ ಹಿಂತಿರುಗಿಸಬೇಕು, ಅವರಿಗೆ ಪಾವತಿಸಲಾಗುವುದಿಲ್ಲ.",
  "Failed to finalize the settlement.": "ಇತ್ಯರ್ಥವನ್ನು ಅಂತಿಮಗೊಳಿಸಲು ಸಾಧ್ಯವಾಗಲಿಲ್ಲ.",
  "Failed to update the settlement.": "ಇತ್ಯರ್ಥವನ್ನು ನವೀಕರಿಸಲು ಸಾಧ್ಯವಾಗಲಿಲ್ಲ.",
  "Finalize": "ಅಂತಿಮಗೊಳಿಸಿ",
  "Finalize this settlement?": "ಈ ಇತ್ಯರ್ಥವನ್ನು ಅಂತಿಮಗೊಳಿಸಬೇಕೇ?",
  "Finalized by {name}": "{name} ಅಂತಿಮಗೊಳಿಸಿದ್ದಾರೆ",
  "Finalizing…": "ಅಂತಿಮಗೊಳಿಸಲಾಗುತ್ತಿದೆ…",
  "Full {required}-day notice served": "ಪೂರ್ಣ {required} ದಿನಗಳ ನೋಟೀಸ್ ಅವಧಿ ಪೂರ್ಣಗೊಂಡಿದೆ",
  "Full & Final Settlement": "ಪೂರ್ಣ ಮತ್ತು ಅಂತಿಮ ಇತ್ಯರ್ಥ",
  "Leave Encashment": "ರಜೆ ನಗದೀಕರಣ",
  "Net Recoverable from Employee": "ಉದ್ಯೋಗಿಯಿಂದ ವಸೂಲಿ ಮಾಡಬೇಕಾದ ನಿವ್ವಳ ಮೊತ್ತ",
  "Notice Period Recovery": "ನೋಟೀಸ್ ಅವಧಿ ವಸೂಲಿ",
  "Notice period shortfall:": "ನೋಟೀಸ್ ಅವಧಿ ಕೊರತೆ:",
  "Other Adjustment (+/−)": "ಇತರ ಹೊಂದಾಣಿಕೆ (+/−)",
  "Other Adjustment Note": "ಇತರ ಹೊಂದಾಣಿಕೆ ಟಿಪ್ಪಣಿ",
  "Other Adjustment: {amount}": "ಇತರ ಹೊಂದಾಣಿಕೆ: {amount}",
  "Pro-rata Salary": "ಅನುಪಾತ ವೇತನ",
  "Pro-rated salary, leave encashment, and notice-period shortfall are computed automatically (CTC ÷ 30, Earned Leave balance) — a starting estimate to review, not a final figure. Gratuity, bonus, reimbursements, advances, and TDS are always entered by hand.": "ಅನುಪಾತ ವೇತನ, ರಜೆ ನಗದೀಕರಣ ಮತ್ತು ನೋಟೀಸ್ ಅವಧಿ ಕೊರತೆಯನ್ನು ತಾನಾಗಿ ಲೆಕ್ಕಾಚಾರ ಮಾಡಲಾಗುತ್ತದೆ (CTC ÷ 30, ಗಳಿಕೆ ರಜೆ ಬಾಕಿ) — ಇದು ಪರಿಶೀಲಿಸಲು ಆರಂಭಿಕ ಅಂದಾಜು, ಅಂತಿಮ ಮೊತ್ತವಲ್ಲ. ಗ್ರಾಚ್ಯುಟಿ, ಬೋನಸ್, ಮರುಪಾವತಿಗಳು, ಮುಂಗಡಗಳು ಮತ್ತು TDS ಅನ್ನು ಯಾವಾಗಲೂ ಕೈಯಾರೆ ನಮೂದಿಸಬೇಕು.",
  "Settlement finalized.": "ಇತ್ಯರ್ಥ ಅಂತಿಮಗೊಂಡಿದೆ.",
  "Settlement updated.": "ಇತ್ಯರ್ಥ ನವೀಕರಿಸಲಾಗಿದೆ.",
  "This is a recovery — the employee owes the company (net payable may be negative)": "ಇದು ವಸೂಲಿ — ಉದ್ಯೋಗಿ ಕಂಪನಿಗೆ ಹಣ ಕೊಡಬೇಕಿದೆ (ನಿವ್ವಳ ಪಾವತಿ ಋಣಾತ್ಮಕವಾಗಿರಬಹುದು)",
  "This locks the full & final settlement at a net payable of {amount}. Once finalized, no field on this settlement — gratuity, bonus, reimbursements, advances, TDS, or adjustments — can be edited again. This cannot be undone.": "ಇದು ಪೂರ್ಣ ಮತ್ತು ಅಂತಿಮ ಇತ್ಯರ್ಥವನ್ನು {amount} ನಿವ್ವಳ ಪಾವತಿಯಲ್ಲಿ ಲಾಕ್ ಮಾಡುತ್ತದೆ. ಅಂತಿಮಗೊಳಿಸಿದ ನಂತರ ಈ ಇತ್ಯರ್ಥದ ಯಾವುದೇ ಕ್ಷೇತ್ರವನ್ನು — ಗ್ರಾಚ್ಯುಟಿ, ಬೋನಸ್, ಮರುಪಾವತಿಗಳು, ಮುಂಗಡಗಳು, TDS ಅಥವಾ ಹೊಂದಾಣಿಕೆಗಳು — ಮತ್ತೆ ತಿದ್ದಲು ಸಾಧ್ಯವಿಲ್ಲ. ಇದನ್ನು ಹಿಂತಿರುಗಿಸಲು ಸಾಧ್ಯವಿಲ್ಲ.",
  "This locks the full & final settlement at a net recoverable from the employee of {amount}. Once finalized, no field on this settlement — gratuity, bonus, reimbursements, advances, TDS, or adjustments — can be edited again. This cannot be undone.": "ಇದು ಪೂರ್ಣ ಮತ್ತು ಅಂತಿಮ ಇತ್ಯರ್ಥವನ್ನು ಉದ್ಯೋಗಿಯಿಂದ ವಸೂಲಿ ಮಾಡಬೇಕಾದ {amount} ನಿವ್ವಳ ಮೊತ್ತದಲ್ಲಿ ಲಾಕ್ ಮಾಡುತ್ತದೆ. ಅಂತಿಮಗೊಳಿಸಿದ ನಂತರ ಈ ಇತ್ಯರ್ಥದ ಯಾವುದೇ ಕ್ಷೇತ್ರವನ್ನು — ಗ್ರಾಚ್ಯುಟಿ, ಬೋನಸ್, ಮರುಪಾವತಿಗಳು, ಮುಂಗಡಗಳು, TDS ಅಥವಾ ಹೊಂದಾಣಿಕೆಗಳು — ಮತ್ತೆ ತಿದ್ದಲು ಸಾಧ್ಯವಿಲ್ಲ. ಇದನ್ನು ಹಿಂತಿರುಗಿಸಲು ಸಾಧ್ಯವಿಲ್ಲ.",
