  "Everyone gets the baseline. On top of that, each person gets the access of the position they hold (set in": "ಎಲ್ಲರಿಗೂ ಮೂಲ ಅನುಮತಿ ಸಿಗುತ್ತದೆ. ಅದರ ಜೊತೆಗೆ, ಪ್ರತಿಯೊಬ್ಬರೂ ತಾವು ಹೊಂದಿರುವ ಹುದ್ದೆಯ ಪ್ರವೇಶವನ್ನು ಪಡೆಯುತ್ತಾರೆ (ಇಲ್ಲಿ ಹೊಂದಿಸಲಾಗಿದೆ:",
  "extra access for just one specific employee, on top of their position.": "ಒಬ್ಬ ನಿರ್ದಿಷ್ಟ ಉದ್ಯೋಗಿಗೆ ಮಾತ್ರ, ಅವರ ಹುದ್ದೆಯ ಜೊತೆಗೆ ಹೆಚ್ಚುವರಿ ಪ್ರವೇಶ.",
  "give the same permissions to many positions at once, e.g. every manager.": "ಹಲವು ಹುದ್ದೆಗಳಿಗೆ ಒಂದೇ ಬಾರಿಗೆ ಒಂದೇ ಅನುಮತಿಗಳನ್ನು ನೀಡಿ, ಉದಾ. ಪ್ರತಿ ಮ್ಯಾನೇಜರ್.",
