  "What every employee can do, whatever their position. Changes take effect the next time each person signs in.": "ಹುದ್ದೆ ಏನೇ ಇರಲಿ, ಪ್ರತಿ ಉದ್ಯೋಗಿ ಏನು ಮಾಡಬಹುದು. ಬದಲಾವಣೆಗಳು ಪ್ರತಿಯೊಬ್ಬರೂ ಮುಂದಿನ ಬಾರಿ ಸೈನ್ ಇನ್ ಮಾಡಿದಾಗ ಜಾರಿಗೆ ಬರುತ್ತವೆ.",
