  "Dashboard banner and notification copy shown to the employee, their team, and their manager on someone's birthday.": "ಯಾರದಾದರೂ ಹುಟ್ಟುಹಬ್ಬದ ದಿನ ಉದ್ಯೋಗಿ, ಅವರ ತಂಡ ಮತ್ತು ಮ್ಯಾನೇಜರ್‌ಗೆ ತೋರಿಸುವ ಡ್ಯಾಶ್‌ಬೋರ್ಡ್ ಬ್ಯಾನರ್ ಮತ್ತು ಅಧಿಸೂಚನೆಯ ಪಠ್ಯ.",
