  "Every ID is 8 digits and purely numeric. Each worker type has its own range, so the first digit tells you the type. The ID is picked automatically at hire; changing someone's type later does not change their existing ID.": "ಪ್ರತಿ ಐಡಿ 8 ಅಂಕಿಗಳ ಸಂಪೂರ್ಣ ಸಂಖ್ಯೆಯಾಗಿರುತ್ತದೆ. ಪ್ರತಿ ಕೆಲಸಗಾರ ಪ್ರಕಾರಕ್ಕೂ ತನ್ನದೇ ಆದ ಶ್ರೇಣಿ ಇದೆ, ಆದ್ದರಿಂದ ಮೊದಲ ಅಂಕಿ ಪ್ರಕಾರವನ್ನು ತಿಳಿಸುತ್ತದೆ. ನೇಮಕದ ಸಮಯದಲ್ಲಿ ಐಡಿ ಸ್ವಯಂಚಾಲಿತವಾಗಿ ಆಯ್ಕೆಯಾಗುತ್ತದೆ; ನಂತರ ಯಾರದಾದರೂ ಪ್ರಕಾರ ಬದಲಾದರೂ ಅವರ ಈಗಿನ ಐಡಿ ಬದಲಾಗುವುದಿಲ್ಲ.",
