  "Reset all": "ಎಲ್ಲವನ್ನೂ ಮರುಹೊಂದಿಸಿ",
  "Save all": "ಎಲ್ಲವನ್ನೂ ಉಳಿಸಿ",
  "Two worker types share some of the same numbers. Change a range so they no longer overlap before saving.": "ಎರಡು ಕೆಲಸಗಾರ ಪ್ರಕಾರಗಳು ಕೆಲವು ಒಂದೇ ಸಂಖ್ಯೆಗಳನ್ನು ಹಂಚಿಕೊಂಡಿವೆ. ಉಳಿಸುವ ಮೊದಲು ಅವು ಮೇಲ್ಪದರವಾಗದಂತೆ ಶ್ರೇಣಿಯನ್ನು ಬದಲಾಯಿಸಿ.",
