  "Education": "ಶಿಕ್ಷಣ",
  "Education and Experience are add/remove lists on the onboarding wizard — Type/Institution (Education) and Employer/Designation (Experience) always show since they identify the entry. Everything else below can be shown, hidden, or made required.": "ಶಿಕ್ಷಣ ಮತ್ತು ಅನುಭವ ಆನ್‌ಬೋರ್ಡಿಂಗ್ ವಿಝಾರ್ಡ್‌ನಲ್ಲಿ ಸೇರಿಸಿ/ತೆಗೆಯುವ ಪಟ್ಟಿಗಳಾಗಿವೆ — ಪ್ರಕಾರ/ಸಂಸ್ಥೆ (ಶಿಕ್ಷಣ) ಮತ್ತು ಉದ್ಯೋಗದಾತ/ಹುದ್ದೆ (ಅನುಭವ) ನಮೂದನ್ನು ಗುರುತಿಸುವುದರಿಂದ ಯಾವಾಗಲೂ ಕಾಣಿಸುತ್ತವೆ. ಕೆಳಗಿನ ಉಳಿದೆಲ್ಲವನ್ನು ತೋರಿಸಬಹುದು, ಮರೆಮಾಡಬಹುದು ಅಥವಾ ಕಡ್ಡಾಯಗೊಳಿಸಬಹುದು.",
