  "Add company allowance options here, then configure their calculation in each salary structure. Deactivating an option prevents new structure components; existing structures and payroll history are unchanged.": "ಕಂಪನಿಯ ಭತ್ಯೆ ಆಯ್ಕೆಗಳನ್ನು ಇಲ್ಲಿ ಸೇರಿಸಿ, ನಂತರ ಪ್ರತಿ ವೇತನ ರಚನೆಯಲ್ಲಿ ಅವುಗಳ ಲೆಕ್ಕಾಚಾರವನ್ನು ಹೊಂದಿಸಿ. ಆಯ್ಕೆಯನ್ನು ನಿಷ್ಕ್ರಿಯಗೊಳಿಸಿದರೆ ಹೊಸ ರಚನೆ ಘಟಕಗಳನ್ನು ಸೇರಿಸಲಾಗುವುದಿಲ್ಲ; ಈಗಿರುವ ರಚನೆಗಳು ಮತ್ತು ಪೇರೋಲ್ ಇತಿಹಾಸ ಬದಲಾಗುವುದಿಲ್ಲ.",
