  "— PF at {employee}% employee / {employer}% employer on basic salary up to ₹{ceiling}.": "— ₹{ceiling} ವರೆಗಿನ ಮೂಲ ವೇತನದ ಮೇಲೆ PF ಉದ್ಯೋಗಿ {employee}% / ಉದ್ಯೋಗದಾತ {employer}%.",
  "— Use company default —": "— ಕಂಪನಿ ಡೀಫಾಲ್ಟ್ ಬಳಸಿ —",
