  "All Company Codes use standard defaults unless overridden": "ಬದಲಾಯಿಸದ ಹೊರತು ಎಲ್ಲಾ ಕಂಪನಿ ಕೋಡ್‌ಗಳು ಪ್ರಮಾಣಿತ ಡೀಫಾಲ್ಟ್‌ಗಳನ್ನು ಬಳಸುತ್ತವೆ",
  "Branch config saved.": "ಶಾಖೆಯ ಕಾನ್ಫಿಗರೇಶನ್ ಉಳಿಸಲಾಗಿದೆ.",
