  "Enter a valid number for {label}.": "{label} ಗೆ ಮಾನ್ಯ ಸಂಖ್ಯೆಯನ್ನು ನಮೂದಿಸಿ.",
  "Failed to remove override.": "ಬದಲಿಯನ್ನು ತೆಗೆದುಹಾಕಲು ಸಾಧ್ಯವಾಗಲಿಲ್ಲ.",
  "Leave blank to use the company default structure": "ಕಂಪನಿಯ ಡೀಫಾಲ್ಟ್ ರಚನೆ ಬಳಸಲು ಖಾಲಿ ಬಿಡಿ",
  "No Company Codes found": "ಯಾವುದೇ ಕಂಪನಿ ಕೋಡ್‌ಗಳು ಕಂಡುಬಂದಿಲ್ಲ",
  "Override below only if this branch has non-standard PF rules (e.g. PF-exempt establishment).": "ಈ ಶಾಖೆಗೆ ಪ್ರಮಾಣಿತವಲ್ಲದ PF ನಿಯಮಗಳಿದ್ದರೆ ಮಾತ್ರ ಕೆಳಗೆ ಬದಲಾಯಿಸಿ (ಉದಾ. PF ವಿನಾಯಿತಿ ಪಡೆದ ಸಂಸ್ಥೆ).",
  "Override removed — branch will use system defaults.": "ಬದಲಿಯನ್ನು ತೆಗೆದುಹಾಕಲಾಗಿದೆ — ಶಾಖೆ ಸಿಸ್ಟಮ್ ಡೀಫಾಲ್ಟ್‌ಗಳನ್ನು ಬಳಸುತ್ತದೆ.",
  "PF Applicable": "PF ಅನ್ವಯಿಸುತ್ತದೆ",
  "PF Employee Rate": "PF ಉದ್ಯೋಗಿ ದರ",
  "PF Employer Rate": "PF ಉದ್ಯೋಗದಾತ ದರ",
  "PF Wage Ceiling cannot be negative.": "PF ವೇತನ ಮಿತಿ ಋಣಾತ್ಮಕವಾಗಿರಬಾರದು.",
  "Provident Fund (PF)": "ಭವಿಷ್ಯ ನಿಧಿ (PF)",
  "Remove Override": "ಬದಲಿಯನ್ನು ತೆಗೆದುಹಾಕಿ",
  "Remove PF override?": "PF ಬದಲಿಯನ್ನು ತೆಗೆದುಹಾಕಬೇಕೇ?",
  "Salary Structure": "ವೇತನ ರಚನೆ",
  "Save Override": "ಬದಲಿಯನ್ನು ಉಳಿಸಿ",
  "Select a Company Code to view its PF configuration": "PF ಕಾನ್ಫಿಗರೇಶನ್ ವೀಕ್ಷಿಸಲು ಕಂಪನಿ ಕೋಡ್ ಆಯ್ಕೆಮಾಡಿ",
  "Select to view or override PF": "PF ವೀಕ್ಷಿಸಲು ಅಥವಾ ಬದಲಿಸಲು ಆಯ್ಕೆಮಾಡಿ",
  "Structure Override": "ರಚನೆ ಬದಲಿ",
  "system defaults": "ಸಿಸ್ಟಮ್ ಡೀಫಾಲ್ಟ್‌ಗಳು",
  "This branch uses": "ಈ ಶಾಖೆ ಬಳಸುತ್ತದೆ",
  "This removes the custom PF configuration for {branch}. The branch will immediately fall back to system defaults ({employee}% employee / {employer}% employer on basic salary up to ₹{ceiling}) for any payroll processed after this. This cannot be undone.": "ಇದು {branch} ಗಾಗಿನ ಕಸ್ಟಮ್ PF ಕಾನ್ಫಿಗರೇಶನ್ ಅನ್ನು ತೆಗೆದುಹಾಕುತ್ತದೆ. ಇದರ ನಂತರ ಪ್ರಕ್ರಿಯೆಗೊಳ್ಳುವ ಯಾವುದೇ ಪೇರೋಲ್‌ಗೆ ಶಾಖೆ ತಕ್ಷಣ ಸಿಸ್ಟಮ್ ಡೀಫಾಲ್ಟ್‌ಗಳಿಗೆ ಮರಳುತ್ತದೆ (₹{ceiling} ವರೆಗಿನ ಮೂಲ ವೇತನದ ಮೇಲೆ ಉದ್ಯೋಗಿ {employee}% / ಉದ್ಯೋಗದಾತ {employer}%). ಇದನ್ನು ರದ್ದುಪಡಿಸಲಾಗುವುದಿಲ್ಲ.",
  "Using system defaults": "ಸಿಸ್ಟಮ್ ಡೀಫಾಲ್ಟ್‌ಗಳನ್ನು ಬಳಸಲಾಗುತ್ತಿದೆ",
  "Wage Ceiling (₹)": "ವೇತನ ಮಿತಿ (₹)",
  "Add State Configuration": "ರಾಜ್ಯ ಕಾನ್ಫಿಗರೇಶನ್ ಸೇರಿಸಿ",
  "Choose a state to configure its professional tax, employee state insurance, and labour welfare fund settings.": "ವೃತ್ತಿ ತೆರಿಗೆ, ಉದ್ಯೋಗಿ ರಾಜ್ಯ ವಿಮೆ ಮತ್ತು ಕಾರ್ಮಿಕ ಕಲ್ಯಾಣ ನಿಧಿ ಸೆಟ್ಟಿಂಗ್‌ಗಳನ್ನು ಹೊಂದಿಸಲು ರಾಜ್ಯವನ್ನು ಆಯ್ಕೆಮಾಡಿ.",
  "Create Config": "ಕಾನ್ಫಿಗರೇಶನ್ ರಚಿಸಿ",
  "Select a state": "ರಾಜ್ಯವನ್ನು ಆಯ್ಕೆಮಾಡಿ",
  "Add Slab": "ಸ್ಲ್ಯಾಬ್ ಸೇರಿಸಿ",
  "Leave Max blank on the last slab to apply it to all higher incomes.": "ಎಲ್ಲಾ ಹೆಚ್ಚಿನ ಆದಾಯಗಳಿಗೆ ಅನ್ವಯಿಸಲು ಕೊನೆಯ ಸ್ಲ್ಯಾಬ್‌ನಲ್ಲಿ ಗರಿಷ್ಠವನ್ನು ಖಾಲಿ ಬಿಡಿ.",
  "Max (₹)": "ಗರಿಷ್ಠ (₹)",
  "Min (₹)": "ಕನಿಷ್ಠ (₹)",
  "No PT slabs defined — add one below": "ಯಾವುದೇ PT ಸ್ಲ್ಯಾಬ್‌ಗಳನ್ನು ವ್ಯಾಖ್ಯಾನಿಸಿಲ್ಲ — ಕೆಳಗೆ ಒಂದನ್ನು ಸೇರಿಸಿ",
  "PT Amount (₹/mo)": "PT ಮೊತ್ತ (₹/ತಿಂಗಳು)",
  "PT Slabs": "PT ಸ್ಲ್ಯಾಬ್‌ಗಳು",
  "Remove slab": "ಸ್ಲ್ಯಾಬ್ ತೆಗೆದುಹಾಕಿ",
  "\"{name}\" will be removed from the active salary structure list. Existing employee compensation records and payslip history will be preserved.": "\"{name}\" ಅನ್ನು ಸಕ್ರಿಯ ವೇತನ ರಚನೆ ಪಟ್ಟಿಯಿಂದ ತೆಗೆದುಹಾಕಲಾಗುತ್ತದೆ. ಈಗಿರುವ ಉದ್ಯೋಗಿ ಪರಿಹಾರ ದಾಖಲೆಗಳು ಮತ್ತು ವೇತನ ಚೀಟಿ ಇತಿಹಾಸವನ್ನು ಉಳಿಸಿಕೊಳ್ಳಲಾಗುತ್ತದೆ.",
  "% of Basic": "ಮೂಲ ವೇತನದ %",
  "% of Basic + DA": "ಮೂಲ ವೇತನ + DA ಯ %",
  "% of CTC": "CTC ಯ %",
  "Activate {name}": "{name} ಸಕ್ರಿಯಗೊಳಿಸಿ",
  "Add Component": "ಘಟಕ ಸೇರಿಸಿ",
  "Add or activate allowance options in Payroll Settings → Allowances first.": "ಮೊದಲು ಪೇರೋಲ್ ಸೆಟ್ಟಿಂಗ್‌ಗಳು → ಭತ್ಯೆಗಳಲ್ಲಿ ಭತ್ಯೆ ಆಯ್ಕೆಗಳನ್ನು ಸೇರಿಸಿ ಅಥವಾ ಸಕ್ರಿಯಗೊಳಿಸಿ.",
  "Add structure": "ರಚನೆ ಸೇರಿಸಿ",
  "Allowance": "ಭತ್ಯೆ",
  "Balances earnings to CTC": "ಗಳಿಕೆಯನ್ನು CTC ಗೆ ಸಮತೋಲನಗೊಳಿಸುತ್ತದೆ",
  "Calculation": "ಲೆಕ್ಕಾಚಾರ",
  "Choose an active allowance from the company catalogue first.": "ಮೊದಲು ಕಂಪನಿ ಪಟ್ಟಿಯಿಂದ ಸಕ್ರಿಯ ಭತ್ಯೆಯನ್ನು ಆಯ್ಕೆಮಾಡಿ.",
