  "Click to deactivate {name}": "{name} ನಿಷ್ಕ್ರಿಯಗೊಳಿಸಲು ಕ್ಲಿಕ್ ಮಾಡಿ",
  "Company allowance": "ಕಂಪನಿ ಭತ್ಯೆ",
  "Component added.": "ಘಟಕವನ್ನು ಸೇರಿಸಲಾಗಿದೆ.",
  "Component change scheduled for {date}.": "ಘಟಕ ಬದಲಾವಣೆಯನ್ನು {date} ಕ್ಕೆ ನಿಗದಿಪಡಿಸಲಾಗಿದೆ.",
  "Component Name": "ಘಟಕದ ಹೆಸರು",
  "Computed automatically from each employee's branch (50% of Basic if the branch is marked Metro, 40% otherwise) — the Percentage field below is ignored for this calculation type.": "ಪ್ರತಿ ಉದ್ಯೋಗಿಯ ಶಾಖೆಯ ಆಧಾರದ ಮೇಲೆ ಸ್ವಯಂಚಾಲಿತವಾಗಿ ಲೆಕ್ಕಹಾಕಲಾಗುತ್ತದೆ (ಶಾಖೆಯನ್ನು ಮೆಟ್ರೋ ಎಂದು ಗುರುತಿಸಿದ್ದರೆ ಮೂಲ ವೇತನದ 50%, ಇಲ್ಲದಿದ್ದರೆ 40%) — ಈ ಲೆಕ್ಕಾಚಾರ ಪ್ರಕಾರಕ್ಕೆ ಕೆಳಗಿನ ಶೇಕಡಾ ಕ್ಷೇತ್ರವನ್ನು ಪರಿಗಣಿಸಲಾಗುವುದಿಲ್ಲ.",
  "Could not delete this salary structure. Please try again.": "ಈ ವೇತನ ರಚನೆಯನ್ನು ಅಳಿಸಲು ಸಾಧ್ಯವಾಗಲಿಲ್ಲ. ದಯವಿಟ್ಟು ಮತ್ತೆ ಪ್ರಯತ್ನಿಸಿ.",
  "Could not schedule this component change.": "ಈ ಘಟಕ ಬದಲಾವಣೆಯನ್ನು ನಿಗದಿಪಡಿಸಲು ಸಾಧ್ಯವಾಗಲಿಲ್ಲ.",
  "Create Salary Structure": "ವೇತನ ರಚನೆ ರಚಿಸಿ",
  "Create Structure": "ರಚನೆ ರಚಿಸಿ",
  "Deactivate {name}": "{name} ನಿಷ್ಕ್ರಿಯಗೊಳಿಸಿ",
  "Deactivate Salary Structure?": "ವೇತನ ರಚನೆಯನ್ನು ನಿಷ್ಕ್ರಿಯಗೊಳಿಸಬೇಕೇ?",
  "Default: next payroll cycle start ({date}).": "ಡೀಫಾಲ್ಟ್: ಮುಂದಿನ ಪೇರೋಲ್ ಚಕ್ರದ ಆರಂಭ ({date}).",
  "Defaults to the next payroll cycle; issued payslips are not recalculated.": "ಡೀಫಾಲ್ಟ್ ಆಗಿ ಮುಂದಿನ ಪೇರೋಲ್ ಚಕ್ರಕ್ಕೆ; ನೀಡಿದ ವೇತನ ಚೀಟಿಗಳನ್ನು ಮರುಲೆಕ್ಕ ಮಾಡಲಾಗುವುದಿಲ್ಲ.",
  "Delete this salary structure": "ಈ ವೇತನ ರಚನೆಯನ್ನು ಅಳಿಸಿ",
  "Disabling {name} affects {count} employee(s). Existing values and historical payslips are retained; the component will be excluded from future calculations from the selected date.": "{name} ನಿಷ್ಕ್ರಿಯಗೊಳಿಸುವುದು {count} ಉದ್ಯೋಗಿ(ಗಳ) ಮೇಲೆ ಪರಿಣಾಮ ಬೀರುತ್ತದೆ. ಈಗಿರುವ ಮೌಲ್ಯಗಳು ಮತ್ತು ಹಿಂದಿನ ವೇತನ ಚೀಟಿಗಳನ್ನು ಉಳಿಸಿಕೊಳ್ಳಲಾಗುತ್ತದೆ; ಆಯ್ಕೆಮಾಡಿದ ದಿನಾಂಕದಿಂದ ಭವಿಷ್ಯದ ಲೆಕ್ಕಾಚಾರಗಳಿಂದ ಘಟಕವನ್ನು ಹೊರಗಿಡಲಾಗುತ್ತದೆ.",
  "Display Order": "ಪ್ರದರ್ಶನ ಕ್ರಮ",
  "e.g. Basic, HRA, Special Allowance": "ಉದಾ. ಮೂಲ ವೇತನ, HRA, ವಿಶೇಷ ಭತ್ಯೆ",
  "e.g. Standard, Management, Executive": "ಉದಾ. ಸ್ಟ್ಯಾಂಡರ್ಡ್, ಮ್ಯಾನೇಜ್‌ಮೆಂಟ್, ಎಕ್ಸಿಕ್ಯುಟಿವ್",
  "Earning": "ಗಳಿಕೆ",
  "Enabling {name} affects {count} employee(s). Previously stored overrides will not be reused; a fresh value must be entered where required.": "{name} ಸಕ್ರಿಯಗೊಳಿಸುವುದು {count} ಉದ್ಯೋಗಿ(ಗಳ) ಮೇಲೆ ಪರಿಣಾಮ ಬೀರುತ್ತದೆ. ಈ ಹಿಂದೆ ಉಳಿಸಿದ ಬದಲಿಗಳನ್ನು ಮರುಬಳಸಲಾಗುವುದಿಲ್ಲ; ಅಗತ್ಯವಿರುವಲ್ಲಿ ಹೊಸ ಮೌಲ್ಯವನ್ನು ನಮೂದಿಸಬೇಕು.",
  "Enter a non-negative value.": "ಋಣಾತ್ಮಕವಲ್ಲದ ಮೌಲ್ಯವನ್ನು ನಮೂದಿಸಿ.",
