  "Set another structure as default before deleting this one.": "ಇದನ್ನು ಅಳಿಸುವ ಮೊದಲು ಬೇರೊಂದು ರಚನೆಯನ್ನು ಡೀಫಾಲ್ಟ್ ಆಗಿ ಹೊಂದಿಸಿ.",
  "Set as company default": "ಕಂಪನಿ ಡೀಫಾಲ್ಟ್ ಆಗಿ ಹೊಂದಿಸಿ",
  "Set as Default": "ಡೀಫಾಲ್ಟ್ ಆಗಿ ಹೊಂದಿಸಿ",
  "Set up a reusable salary template. You can add earnings, allowances, and deductions after creating it.": "ಮರುಬಳಸಬಹುದಾದ ವೇತನ ಟೆಂಪ್ಲೇಟ್ ಹೊಂದಿಸಿ. ರಚಿಸಿದ ನಂತರ ಗಳಿಕೆಗಳು, ಭತ್ಯೆಗಳು ಮತ್ತು ಕಡಿತಗಳನ್ನು ಸೇರಿಸಬಹುದು.",
  "Structures": "ರಚನೆಗಳು",
  "Taxable": "ತೆರಿಗೆಗೆ ಒಳಪಡುವ",
  "The new component order will apply to {count} affected employee(s).": "ಹೊಸ ಘಟಕ ಕ್ರಮ ಪರಿಣಾಮ ಬೀರುವ {count} ಉದ್ಯೋಗಿ(ಗಳಿಗೆ) ಅನ್ವಯಿಸುತ್ತದೆ.",
  "The remaining CTC after other enabled earnings and statutory employer contributions.": "ಇತರ ಸಕ್ರಿಯ ಗಳಿಕೆಗಳು ಮತ್ತು ಕಾನೂನುಬದ್ಧ ಉದ್ಯೋಗದಾತರ ಕೊಡುಗೆಗಳ ನಂತರ ಉಳಿದ CTC.",
  "Use this structure as the default when setting up employee compensation.": "ಉದ್ಯೋಗಿ ಪರಿಹಾರವನ್ನು ಹೊಂದಿಸುವಾಗ ಈ ರಚನೆಯನ್ನು ಡೀಫಾಲ್ಟ್ ಆಗಿ ಬಳಸಿ.",
  "{label} must be between 0 and 100.": "{label} 0 ಮತ್ತು 100 ರ ನಡುವೆ ಇರಬೇಕು.",
  "A config for this state may already exist.": "ಈ ರಾಜ್ಯಕ್ಕೆ ಕಾನ್ಫಿಗರೇಶನ್ ಈಗಾಗಲೇ ಇರಬಹುದು.",
  "An employee averaging at or below the daily wage above is exempt from their own ESI share. The employer share is still due.": "ಮೇಲಿನ ದೈನಂದಿನ ವೇತನದ ಸರಾಸರಿ ಅಥವಾ ಅದಕ್ಕಿಂತ ಕಡಿಮೆ ಇರುವ ಉದ್ಯೋಗಿಗೆ ತಮ್ಮ ESI ಪಾಲಿನಿಂದ ವಿನಾಯಿತಿ ಇರುತ್ತದೆ. ಉದ್ಯೋಗದಾತರ ಪಾಲು ಇನ್ನೂ ಪಾವತಿಸಬೇಕಾಗುತ್ತದೆ.",
