  "Employees' projects are managed in Project Budgeting and shown in AIRA. Problems and employees AIRA could not match appear here.": "ಉದ್ಯೋಗಿಗಳ ಪ್ರಾಜೆಕ್ಟ್‌ಗಳನ್ನು ಪ್ರಾಜೆಕ್ಟ್ ಬಜೆಟಿಂಗ್‌ನಲ್ಲಿ ನಿರ್ವಹಿಸಲಾಗುತ್ತದೆ ಮತ್ತು AIRA ದಲ್ಲಿ ತೋರಿಸಲಾಗುತ್ತದೆ. ಸಮಸ್ಯೆಗಳು ಮತ್ತು AIRA ಹೊಂದಿಸಲು ಸಾಧ್ಯವಾಗದ ಉದ್ಯೋಗಿಗಳು ಇಲ್ಲಿ ಕಾಣಿಸುತ್ತಾರೆ.",
