  "Pick a saved location, capture a new one, or search an address — this is what your clock-in on approved WFH days gets checked against.": "ಉಳಿಸಿದ ಸ್ಥಳವನ್ನು ಆಯ್ಕೆಮಾಡಿ, ಹೊಸದನ್ನು ಸೆರೆಹಿಡಿಯಿರಿ ಅಥವಾ ವಿಳಾಸವನ್ನು ಹುಡುಕಿ — ಅನುಮೋದಿತ WFH ದಿನಗಳಲ್ಲಿ ನಿಮ್ಮ ಕ್ಲಾಕ್-ಇನ್ ಅನ್ನು ಇದರ ವಿರುದ್ಧ ಪರಿಶೀಲಿಸಲಾಗುತ್ತದೆ.",
