  "Select a saved location, capture your current one, or search an address before submitting — this is what your clock-in will be checked against on WFH days.": "ಸಲ್ಲಿಸುವ ಮೊದಲು ಉಳಿಸಿದ ಸ್ಥಳವನ್ನು ಆಯ್ಕೆಮಾಡಿ, ನಿಮ್ಮ ಪ್ರಸ್ತುತ ಸ್ಥಳವನ್ನು ಸೆರೆಹಿಡಿಯಿರಿ ಅಥವಾ ವಿಳಾಸವನ್ನು ಹುಡುಕಿ — WFH ದಿನಗಳಲ್ಲಿ ನಿಮ್ಮ ಕ್ಲಾಕ್-ಇನ್ ಅನ್ನು ಇದರ ವಿರುದ್ಧ ಪರಿಶೀಲಿಸಲಾಗುತ್ತದೆ.",
  "Source": "ಮೂಲ",
