  "tab. Open one to see its status or cancel it while it is still pending.": "ಟ್ಯಾಬ್‌ನಲ್ಲಿ. ಸ್ಥಿತಿಯನ್ನು ನೋಡಲು ಅಥವಾ ಇನ್ನೂ ಬಾಕಿ ಇರುವಾಗ ರದ್ದುಮಾಡಲು ಒಂದನ್ನು ತೆರೆಯಿರಿ.",
  "View My Requests": "ನನ್ನ ವಿನಂತಿಗಳನ್ನು ವೀಕ್ಷಿಸಿ",
  "Why do you need to work from home? Your approver will read this.": "ನೀವು ಮನೆಯಿಂದ ಏಕೆ ಕೆಲಸ ಮಾಡಬೇಕು? ನಿಮ್ಮ ಅನುಮೋದಕರು ಇದನ್ನು ಓದುತ್ತಾರೆ.",
  "Your browser doesn't support location capture.": "ನಿಮ್ಮ ಬ್ರೌಸರ್ ಸ್ಥಳ ಸೆರೆಹಿಡಿಯುವಿಕೆಯನ್ನು ಬೆಂಬಲಿಸುವುದಿಲ್ಲ.",
  "Your existing requests are listed under": "ನಿಮ್ಮ ಈಗಿರುವ ವಿನಂತಿಗಳನ್ನು ಇಲ್ಲಿ ಪಟ್ಟಿ ಮಾಡಲಾಗಿದೆ:",
