  "Address matches": "ವಿಳಾಸ ಹೊಂದಿಕೆಯಾಗುತ್ತದೆ",
  "House / street, area, city, pincode": "ಮನೆ / ರಸ್ತೆ, ಪ್ರದೇಶ, ನಗರ, ಪಿನ್‌ಕೋಡ್",
  "No match found. Try adding the area, city or pincode.": "ಯಾವುದೇ ಹೊಂದಾಣಿಕೆ ಕಂಡುಬಂದಿಲ್ಲ. ಪ್ರದೇಶ, ನಗರ ಅಥವಾ ಪಿನ್‌ಕೋಡ್ ಸೇರಿಸಿ ನೋಡಿ.",
  "The address search failed. Please try again.": "ವಿಳಾಸ ಹುಡುಕಾಟ ವಿಫಲವಾಯಿತು. ದಯವಿಟ್ಟು ಮತ್ತೆ ಪ್ರಯತ್ನಿಸಿ.",
