  "An approved request can't be cancelled from here. If your plans changed, ask your manager or HR.": "ಅನುಮೋದಿತ ವಿನಂತಿಯನ್ನು ಇಲ್ಲಿಂದ ರದ್ದುಮಾಡಲಾಗುವುದಿಲ್ಲ. ನಿಮ್ಮ ಯೋಜನೆಗಳು ಬದಲಾಗಿದ್ದರೆ ನಿಮ್ಮ ಮ್ಯಾನೇಜರ್ ಅಥವಾ HR ಅವರನ್ನು ಕೇಳಿ.",
  "Cancel this work-from-home request?": "ಈ ಮನೆಯಿಂದ ಕೆಲಸದ ವಿನಂತಿಯನ್ನು ರದ್ದುಮಾಡಬೇಕೇ?",
