  "A nominee is picked from the family list, and there is nobody in it yet. Add a family member with a name above, then add the nominee.": "ನಾಮನಿರ್ದೇಶಿತರನ್ನು ಕುಟುಂಬ ಪಟ್ಟಿಯಿಂದ ಆಯ್ಕೆ ಮಾಡಲಾಗುತ್ತದೆ, ಆದರೆ ಅದರಲ್ಲಿ ಇನ್ನೂ ಯಾರೂ ಇಲ್ಲ. ಮೇಲೆ ಹೆಸರಿನೊಂದಿಗೆ ಕುಟುಂಬ ಸದಸ್ಯರನ್ನು ಸೇರಿಸಿ, ನಂತರ ನಾಮನಿರ್ದೇಶಿತರನ್ನು ಸೇರಿಸಿ.",
  "Add a family member with a name above before adding a nominee.": "ನಾಮನಿರ್ದೇಶಿತರನ್ನು ಸೇರಿಸುವ ಮೊದಲು ಮೇಲೆ ಹೆಸರಿನೊಂದಿಗೆ ಕುಟುಂಬ ಸದಸ್ಯರನ್ನು ಸೇರಿಸಿ.",
  "Add the people who depend on the employee or who may be nominated below. A person is added once and can be picked as a nominee.": "ಉದ್ಯೋಗಿಯ ಮೇಲೆ ಅವಲಂಬಿತರಾದ ಅಥವಾ ನಾಮನಿರ್ದೇಶನಗೊಳ್ಳಬಹುದಾದ ಜನರನ್ನು ಕೆಳಗೆ ಸೇರಿಸಿ. ಒಬ್ಬ ವ್ಯಕ್ತಿಯನ್ನು ಒಮ್ಮೆ ಸೇರಿಸಿದರೆ ಸಾಕು, ಅವರನ್ನು ನಾಮನಿರ್ದೇಶಿತರಾಗಿ ಆಯ್ಕೆ ಮಾಡಬಹುದು.",
  "Another {relationship} is already listed.": "ಇನ್ನೊಬ್ಬ {relationship} ಈಗಾಗಲೇ ಪಟ್ಟಿಯಲ್ಲಿದ್ದಾರೆ.",
  "Each scheme's shares should add up to 100% across its nominees. Pick nominees from the family list above.": "ಪ್ರತಿ ಯೋಜನೆಯ ಪಾಲುಗಳು ಅದರ ನಾಮನಿರ್ದೇಶಿತರ ನಡುವೆ ಒಟ್ಟು 100% ಆಗಿರಬೇಕು. ಮೇಲಿನ ಕುಟುಂಬ ಪಟ್ಟಿಯಿಂದ ನಾಮನಿರ್ದೇಶಿತರನ್ನು ಆಯ್ಕೆಮಾಡಿ.",
  "EPF / Gratuity nomination": "EPF / ಗ್ರಾಚ್ಯುಟಿ ನಾಮನಿರ್ದೇಶನ",
  "No family members yet. This is optional; use the buttons above to add someone.": "ಇನ್ನೂ ಯಾವುದೇ ಕುಟುಂಬ ಸದಸ್ಯರಿಲ್ಲ. ಇದು ಐಚ್ಛಿಕ; ಯಾರನ್ನಾದರೂ ಸೇರಿಸಲು ಮೇಲಿನ ಬಟನ್‌ಗಳನ್ನು ಬಳಸಿ.",
