  "{name} is under 18. Check whether a guardian must be named for a minor nominee.": "{name} 18 ವರ್ಷಕ್ಕಿಂತ ಕಡಿಮೆ ವಯಸ್ಸಿನವರು. ಅಪ್ರಾಪ್ತ ನಾಮನಿರ್ದೇಶಿತರಿಗೆ ಪಾಲಕರನ್ನು ಹೆಸರಿಸಬೇಕೇ ಎಂದು ಪರಿಶೀಲಿಸಿ.",
