  "No family members added.": "ಯಾವುದೇ ಕುಟುಂಬ ಸದಸ್ಯರನ್ನು ಸೇರಿಸಿಲ್ಲ.",
  "No prior experience added.": "ಯಾವುದೇ ಹಿಂದಿನ ಅನುಭವವನ್ನು ಸೇರಿಸಿಲ್ಲ.",
  "Nominee: {name}": "ನಾಮನಿರ್ದೇಶಿತ: {name}",
  "Nothing configured for this section.": "ಈ ವಿಭಾಗಕ್ಕೆ ಏನನ್ನೂ ಹೊಂದಿಸಿಲ್ಲ.",
  "on any section to go back and change it — nothing is sent to HR until you press": "ಯಾವುದೇ ವಿಭಾಗದಲ್ಲಿ ಹಿಂದಕ್ಕೆ ಹೋಗಿ ಬದಲಾಯಿಸಲು — ನೀವು ಒತ್ತುವವರೆಗೆ HR ಗೆ ಏನನ್ನೂ ಕಳುಹಿಸಲಾಗುವುದಿಲ್ಲ",
  "Optional — not submitted": "ಐಚ್ಛಿಕ — ಸಲ್ಲಿಸಿಲ್ಲ",
  "Required — not yet submitted": "ಕಡ್ಡಾಯ — ಇನ್ನೂ ಸಲ್ಲಿಸಿಲ್ಲ",
  "Review everything below before submitting. Use": "ಸಲ್ಲಿಸುವ ಮೊದಲು ಕೆಳಗಿನ ಎಲ್ಲವನ್ನೂ ಪರಿಶೀಲಿಸಿ. ಬಳಸಿ",
  "{name} preview": "{name} ಪೂರ್ವವೀಕ್ಷಣೆ",
  "Checked against every other employee before the upload goes through — enter it first.": "ಅಪ್‌ಲೋಡ್ ಆಗುವ ಮೊದಲು ಇತರ ಎಲ್ಲಾ ಉದ್ಯೋಗಿಗಳ ವಿರುದ್ಧ ಪರಿಶೀಲಿಸಲಾಗುತ್ತದೆ — ಮೊದಲು ಇದನ್ನು ನಮೂದಿಸಿ.",
  "Drag and drop a file onto any row below, or click Upload. Accepted: PDF, JPG, PNG · Max 5 MB each.": "ಕೆಳಗಿನ ಯಾವುದೇ ಸಾಲಿಗೆ ಫೈಲ್ ಅನ್ನು ಎಳೆದು ಬಿಡಿ, ಅಥವಾ ಅಪ್‌ಲೋಡ್ ಕ್ಲಿಕ್ ಮಾಡಿ. ಸ್ವೀಕೃತ: PDF, JPG, PNG · ಪ್ರತಿಯೊಂದು ಗರಿಷ್ಠ 5 MB.",
  "e.g. ABCDE1234F": "ಉದಾ. ABCDE1234F",
  "File is too large ({size} MB) — the limit is 5 MB.": "ಫೈಲ್ ತುಂಬಾ ದೊಡ್ಡದಾಗಿದೆ ({size} MB) — ಮಿತಿ 5 MB.",
  "Only PDF, JPG, and PNG files are accepted.": "PDF, JPG ಮತ್ತು PNG ಫೈಲ್‌ಗಳನ್ನು ಮಾತ್ರ ಸ್ವೀಕರಿಸಲಾಗುತ್ತದೆ.",
  "PAN Number": "PAN ಸಂಖ್ಯೆ",
  "Remove this document": "ಈ ದಾಖಲೆಯನ್ನು ತೆಗೆದುಹಾಕಿ",
  "Face ID approved": "Face ID ಅನುಮೋದಿಸಲಾಗಿದೆ",
  "Face ID not yet registered": "Face ID ಇನ್ನೂ ನೋಂದಾಯಿಸಿಲ್ಲ",
  "Face ID registered": "Face ID ನೋಂದಾಯಿಸಲಾಗಿದೆ",
  "Face ID rejected — please register again": "Face ID ತಿರಸ್ಕರಿಸಲಾಗಿದೆ — ದಯವಿಟ್ಟು ಮತ್ತೆ ನೋಂದಾಯಿಸಿ",
  "Face ID submitted — pending HR approval": "Face ID ಸಲ್ಲಿಸಲಾಗಿದೆ — HR ಅನುಮೋದನೆ ಬಾಕಿ",
  "Register Again": "ಮತ್ತೆ ನೋಂದಾಯಿಸಿ",
  "Register Face ID": "Face ID ನೋಂದಾಯಿಸಿ",
  "You won't be able to submit your onboarding profile until this step is complete.": "ಈ ಹಂತ ಪೂರ್ಣಗೊಳ್ಳುವವರೆಗೆ ನಿಮ್ಮ ಆನ್‌ಬೋರ್ಡಿಂಗ್ ಪ್ರೊಫೈಲ್ ಅನ್ನು ಸಲ್ಲಿಸಲು ಸಾಧ್ಯವಾಗುವುದಿಲ್ಲ.",
  "Your organisation requires a registered face ID for web clock-in/out. Register once here — we run a quick liveness check to confirm it's really you, and it takes effect immediately.": "ವೆಬ್ ಕ್ಲಾಕ್-ಇನ್/ಔಟ್‌ಗೆ ನಿಮ್ಮ ಸಂಸ್ಥೆಗೆ ನೋಂದಾಯಿತ Face ID ಅಗತ್ಯವಿದೆ. ಇಲ್ಲಿ ಒಮ್ಮೆ ನೋಂದಾಯಿಸಿ — ಅದು ನೀವೇ ಎಂದು ದೃಢೀಕರಿಸಲು ತ್ವರಿತ ಲೈವ್‌ನೆಸ್ ಪರಿಶೀಲನೆ ನಡೆಸುತ್ತೇವೆ, ಮತ್ತು ಅದು ತಕ್ಷಣ ಜಾರಿಗೆ ಬರುತ್ತದೆ.",
  "Your organisation requires a registered face ID for web clock-in/out. Register once here — we run a quick liveness check to confirm it's really you, then send it to HR for approval.": "ವೆಬ್ ಕ್ಲಾಕ್-ಇನ್/ಔಟ್‌ಗೆ ನಿಮ್ಮ ಸಂಸ್ಥೆಗೆ ನೋಂದಾಯಿತ Face ID ಅಗತ್ಯವಿದೆ. ಇಲ್ಲಿ ಒಮ್ಮೆ ನೋಂದಾಯಿಸಿ — ಅದು ನೀವೇ ಎಂದು ದೃಢೀಕರಿಸಲು ತ್ವರಿತ ಲೈವ್‌ನೆಸ್ ಪರಿಶೀಲನೆ ನಡೆಸಿ, ನಂತರ ಅನುಮೋದನೆಗಾಗಿ HR ಗೆ ಕಳುಹಿಸುತ್ತೇವೆ.",
  "{percent}% Score": "{percent}% ಅಂಕ",
