  "Choose the state and city. The Company Code is made from the city for you.": "ರಾಜ್ಯ ಮತ್ತು ನಗರವನ್ನು ಆಯ್ಕೆಮಾಡಿ. ಕಂಪನಿ ಕೋಡ್ ಅನ್ನು ನಗರದಿಂದ ನಿಮಗಾಗಿ ರಚಿಸಲಾಗುತ್ತದೆ.",
