  "My goals and feedback": "ನನ್ನ ಗುರಿಗಳು ಮತ್ತು ಪ್ರತಿಕ್ರಿಯೆ",
  "Name and address": "ಹೆಸರು ಮತ್ತು ವಿಳಾಸ",
