  "Pick the person who looks after this office. You can skip this and add them later.": "ಈ ಕಚೇರಿಯನ್ನು ನೋಡಿಕೊಳ್ಳುವವರನ್ನು ಆಯ್ಕೆಮಾಡಿ. ಇದನ್ನು ಬಿಟ್ಟು ನಂತರ ಸೇರಿಸಬಹುದು.",
